pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let res_sq = post_res * post_res;

    // Penalize small residuals (dead space) more heavily early in the stream
    // to encourage tighter packing while the stream has high entropy.
    // As the stream progresses, favor packing that leaves space for future items.
    let dead_space_penalty = (1.0 - progress) * (100.0 - post_res).powi(2);

    // Encourage filling bins that are already "near" the average fullness
    // to minimize the variance of residuals across open bins.
    let variance_penalty = (post_res - mean_residual).abs() * 0.5;

    // Lookahead logic: if next_item_size is large, avoid leaving a residual
    // smaller than that size, as it creates "orphaned" space.
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
        (next_item_size as f64 - post_res) * 2.0
    } else {
        0.0
    };

    // New bin logic: if we have many fitting bins, heavily penalize opening a new one.
    // If we have very few, relax the penalty to allow for better future fits.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (fitting_bins_count as f64 * 50.0) + (progress * 100.0)
    } else {
        0.0
    };

    // Base score is the post_residual itself (Best Fit variant).
    // Subtracting the lookahead and variance components to favor better state alignment.
    let mut score = res_sq + dead_space_penalty + variance_penalty + lookahead_penalty + new_bin_penalty;

    // Favor bins that are more "congested" (smaller post_residual) 
    // to keep the number of open bins minimized.
    score -= (1.0 - progress) * post_res;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: scales with progress to favor consolidation early
    // and aggressive packing late.
    if is_new_bin {
        score += 25.0 * (1.0 - progress).powf(0.5);
    }

    // Heuristic: Penalize leaving small gaps that are unlikely to fit future items.
    // If the post_residual is in the "dead zone" (between 1 and 9), penalize it
    // because no item size (min 10) can fit there.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: If a next item exists, penalize bins that leave residual space
    // smaller than the next item if we have other options.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0 * (1.0 - progress);
    }

    // Global state optimization: Penalize creating too many bins by scaling the 
    // baseline score by the number of open bins, weighted by the mean residual.
    // This forces the algorithm to consolidate into bins with higher mean residuals.
    if !is_new_bin {
        score += (open_bins_count as f64 * 0.5) * (1.0 - (mean_residual / bin_capacity as f64));
    }

    // Criticality: If this is the only bin that fits, reduce the penalty significantly
    // to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We penalize small residuals (fragmentation) by applying an exponential weight
    // as we progress through the stream to favor tighter packing late-game.
    let fragmentation_penalty = (1.0 / (post + 0.1)).powf(1.5 + progress);

    // Lookahead logic: if next_item_size is large, penalize small post_residuals
    // that would make the next item impossible to fit.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // If this is a new bin, apply a structural penalty that decays as the 
    // number of open bins increases (to consolidate) and as we approach 
    // the end of the stream (to reduce bin count).
    let is_new_bin = bin_residual == bin_capacity;
    let open_bin_penalty = if is_new_bin {
        (100.0 - (open_bins_count as f64 * 2.0)) * (1.0 - (progress * 0.5))
    } else {
        0.0
    };

    // Final score: prioritize bins that leave just enough space for future items,
    // minimize fragmentation, and discourage opening new bins unless necessary.
    let mut score = post + fragmentation_penalty + lookahead_penalty + open_bin_penalty;

    // If fitting_bins_count is 1 and this is the only bin that fits, 
    // heavily reward it to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily punish creating "dead zones"
    // (space too small for common items).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Awareness:
    // If we have a next item, try to leave a residual that fits it perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect alignment with next item
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.5;
        } else {
            // Penalty for stranding the next item
            score += 40.0;
        }
    }

    // 3. Fragmentation Control:
    // If this is the only bin that fits, we are forced to take it. 
    // If it's a new bin, penalize based on current mean_residual to avoid opening bins too early.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to how "full" the existing ones are.
        score += 25.0 + (mean_residual * 0.5);
    } else {
        // Reward utilizing existing bins to reduce open_bins_count
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Lookahead/Density scaling:
    // As the stream progresses, become more conservative about wasting space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 5. Modulo-based "Bin-Filling" Logic:
    // Favor bins that result in residuals which are multiples of 10 (common item sizes)
    if post_residual % 10 == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement
    let mut score = post_res;

    // Penalty for creating a bin that is too small for common future items.
    // If post_residual is small (e.g., < 20), it's likely "dead space" that cannot fit 
    // any future items (since min size is 10, but effective range is usually larger).
    // We penalize very small residuals exponentially.
    if post_res > 0.0 && post_res < 25.0 {
        score += (25.0 - post_res).powf(1.5);
    }

    // Lookahead logic: If the next item cannot fit in this bin, penalize the current placement
    // if the current placement leaves a residual that is just slightly too small for the next item.
    if next_item_size > 0 && post_res < next_item_size as f64 {
        score += (next_item_size as f64 - post_res) * 0.5;
    }

    // Dynamic adjustment based on stream progress:
    // As the stream progresses, we want to be more aggressive about packing tightly
    // to minimize the number of open bins.
    let density_pressure = (open_bins_count as f64 / (1.0 + progress * 10.0)).sqrt();
    score += density_pressure * 5.0;

    // If this is the only bin that can fit the item, we reward it to avoid opening a new bin
    // unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // If we are considering opening a new bin (bin_residual == bin_capacity),
    // apply a cost based on the current mean residual of existing bins.
    // If the mean residual is already high, opening a new bin is inefficient.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: The post_residual is the primary metric. 
    // We prefer smaller post_residuals (Best Fit).
    let mut score = post;

    // Penalty for creating a "fragment" (a residual too small for any likely item).
    // If the post_residual is less than the smallest typical item (10), 
    // it is highly likely to be wasted space.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: If the next item could have fit in the current bin 
    // but the current placement makes it impossible, penalize the placement.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 2.0;
    }

    // Dynamic adaptation: As we reach the end of the stream, prioritize 
    // clearing bins (minimizing open_bins_count) over individual fit quality.
    let closure_pressure = progress * (open_bins_count as f64);
    score += closure_pressure * 0.5;

    // If this is a new bin (bin_residual == bin_capacity), 
    // we only want to open it if existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high, but decreases slightly 
        // if the mean residual is already quite low (suggesting we are stuck).
        score = 85.0 - (mean_residual * 0.2);
    } else {
        // If it's an existing bin, slightly favor bins that are already "fuller"
        // to keep the number of open bins low.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Final non-linear coupling: Amplify the score if we are nearing the end
    // of the stream to force tighter packing of remaining items.
    score * (1.0 + (progress * 0.5))
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space: lower post_residual is generally better (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for creating a new bin: only open a new bin if the "Best Fit" is very poor.
    if is_new_bin {
        // We only consider opening a new bin if all current bins have poor fit potential.
        // We set the baseline cost of a new bin high, scaling it down as the stream progresses
        // to avoid fragmentation toward the end.
        score = 45.0 - (progress * 15.0);
    } else {
        // Penalty for creating 'dead space' (the post_residual).
        // Non-linear interaction: as we approach the end of the stream, 
        // we become more sensitive to small residuals that might remain unused.
        score += (post_residual as f64).powf(1.2 + (0.5 * progress));

        // Lookahead heuristic: If the next item exists, penalize bins that cannot fit it
        // after this placement.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 25.0 * (1.0 - progress);
            }
        }

        // Favor bins that align with the global average residual to keep bin states uniform,
        // which helps in keeping future items packable.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // If this is the last fitting bin, give it a slight preference boost to avoid opening
    // a new bin unnecessarily (preventing the "New Bin" from winning by default).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (Best Fit Decreasing logic)
    // We penalize post_residuals that are too small to fit common items (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead synergy: If the next item fits perfectly into the remaining gap, 
    // heavily reward this bin selection.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_waste = (post_residual - next_item_size) as f64;
        score -= (100.0 - gap_waste);
    }

    // 3. Global state adaptation: If we are late in the stream, prioritize closing bins
    // to keep the total count low.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Mean residual balancing: Penalize bins that deviate significantly from the 
    // average residual of other open bins to encourage uniform packing.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. New bin handling: Only open a new bin if the current fit is extremely poor
    // or if it's the only option.
    if bin_residual == bin_capacity {
        // High threshold to open a new bin; only do it if the average residual 
        // is already very low, meaning we are struggling to fit items into existing space.
        if mean_residual > 20.0 {
            score -= 40.0;
        } else {
            score += 100.0;
        }
    }

    // 6. Urgency: If this is the last chance for this item (fitting_bins_count == 1),
    // reduce the score to ensure it is selected over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) more heavily as the stream progresses
    // to encourage tighter packing toward the end.
    let dead_space_penalty = (1.0 - (post / bin_capacity as f64)).powf(2.0 + progress * 2.0) * 100.0;

    // Reward bins that can accommodate the next item (lookahead look-up)
    // If next_item_size fits in the post_residual, reduce score.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Heuristic for opening a new bin:
    // If this is a new bin, base score is high. 
    // We only open if the penalty of forcing a fit into existing bins outweighs this.
    let mut score = post + dead_space_penalty + lookahead_bonus;

    if bin_residual == bin_capacity {
        // New bin candidate: Only select if existing bins are poor fits.
        // We normalize the "new bin" cost by the average residual of current bins.
        score = 45.0 + (mean_residual * 0.5) - (progress * 10.0);
    } else {
        // Existing bin: Penalize if it's the last chance (fitting_bins_count == 1)
        // and the resulting residual is highly inefficient.
        if fitting_bins_count == 1 && post > 20 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'unusable' space (gaps smaller than the minimum likely item size)
    // We heavily penalize post_residuals that are too small to fit typical items but too large to be zero.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Reward bins that lead to a perfect fit (zero residual)
    if post_residual == 0 {
        score -= 20.0;
    }

    // Strategic pressure: if we are running out of items, minimize bin count aggressively
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 2.0);

    // Lookahead logic: if the next item is large, avoid leaving a residual that cannot accommodate it
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // New bin penalty: If this is an empty bin (bin_residual == bin_capacity), 
    // we only want to open it if existing bins are poor fits.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, reduced if we have too many open bins already 
        // to prevent fragmentation, or increased if we have few bins open.
        score += 65.0 - (open_bins_count as f64 * 0.5);
    } else {
        // Favor bins that align with the mean density of current open bins
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // If this is the only bin that can fit the item, prioritize it to avoid creating new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead zones" (small residuals that are hard to fill).
    // We penalize residuals in the (0, 10) range heavily as they are likely unusable.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If the current bin's post_residual is too small for the next item, add a penalty.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Dynamic adaptation: As the stream progresses, prioritize tighter packing to conserve space.
    // We increase the weight of the residual penalty as we approach the end of the stream.
    score += (post * progress * 2.0);

    // If this is a new bin (bin_residual == bin_capacity), calculate its base cost.
    // We make opening a new bin increasingly expensive unless the fit in existing bins is poor.
    if bin_residual == bin_capacity {
        // Base cost for a new bin is high to encourage filling existing bins.
        // We reduce this cost slightly if we have many bins already (to avoid fragmentation).
        score = 45.0 - (open_bins_count as f64 * 0.1) + (progress * 15.0);
    } else {
        // If it's an existing bin, favor those that are closer to the mean residual
        // to keep bin utilization balanced.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    // If this is the last chance to fit the item in an existing bin, apply a strong discount.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead" gaps (1..10) 
    // that are unlikely to fit future items. Balance this against total open bin pressure.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit the smallest 
    // likely items (10), treat it as highly undesirable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item can fit in the remaining space, 
    // reward this placement to keep the bin useful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global Efficiency: If this is an existing bin (not a new one), 
    // favor bins that are already "tight" (low residual) to keep open_bins_count low.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.5;
    } else {
        // Penalty for opening a new bin: increase as we near the end of the stream 
        // to force consolidation.
        score += 20.0 + (step_index as f64 / total_items as f64) * 30.0;
    }

    // 4. Scarcity Adjustment: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. Mean residual alignment: Avoid creating bins that are significantly 
    // worse than the average current bin.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We target residuals that are multiples of common item sizes (harmonic spacing).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0;
    }

    // Lookahead logic: if the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // Encourage filling bins that are already partially full (reduce open_bins_count).
    // We normalize the filling density.
