    // 7. Harmonic scaling based on mean_residual:
    // If the average bin is already quite full, be more selective about creating new fragments.
    if mean_residual < 20.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post_res = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space": gaps smaller than the minimum likely item (approx 10-15)
    // are extremely expensive as they cannot easily accommodate future items.
    let mut score = post_res;
    if post_res > 0.0 && post_res < 15.0 {
        score += 45.0 * (1.0 - (post_res / 15.0));
    }

    // 2. Penalize opening new bins if there are existing bins that can fit the item,
    // unless the current bin state is significantly better than the mean.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin prematurely
            score += 120.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 3. Lookahead: If next_item_size is large, favor bins that can still accommodate it.
        if next_item_size > 0 && post_res < next_item_size as f64 {
            score += 30.0;
        }

        // 4. Pressure: As the stream progresses, prioritize closing bins (minimizing mean_residual)
        // by filling bins that are already close to capacity.
        score += (mean_residual - post_res) * progress;
    }

    // 5. Global Efficiency: Penalize high open_bins_count to encourage dense packing.
    score += (open_bins_count as f64).powf(1.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common items).
    // If post_residual is < 10, it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: Reward bins that perfectly fit the current OR next item.
    // If the post_residual matches the next_item_size, we create a high-probability future fit.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // 3. Pressure management: If we are running out of bins or near the end of the stream,
    // be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high.
        score += 40.0;
        // As we reach the end of the stream, penalize opening new bins more heavily to force consolidation.
        score += progress * 30.0;
    }

    // 4. Distribution balancing: Favor bins that stay close to the current mean residual
    // to prevent fragmentation of the bin space.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Critical path: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Penalty for creating bins that are significantly emptier than the average.
    if post_residual > (mean_residual as u32 + 20) {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

