    // If post_residual is < 10, it's likely unusable for most items.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // Lookahead logic: If the next item is large, prioritize bins that can fit it.
    // If current bin can fit the next item, reduce score (reward).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Global state pressure: If we have many open bins, prioritize filling them to avoid fragmentation.
    // If fitting_bins_count is low, we are running out of options for this item.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Dynamic horizon: As we approach the end of the stream, be more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // This is a candidate for a new bin.
        // Penalty for new bins increases as we get closer to the end of the stream.
        score += 20.0 + (30.0 * progress);

        // If we have many open bins already, make opening a new one very expensive.
        score += (open_bins_count as f64) * 5.0;
    } else {
        // Reward filling existing bins that are close to the mean_residual of the pack.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
