    }

    // Lookahead interaction: if the next item is large, prioritize bins that
    // leave enough space for it (or minimize the wasted space if it doesn't fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= (100.0 - (post_residual - next_item_size) as f64).sqrt();
        } else {
