    if !is_new_bin && fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Coupling with mean_residual: discourage bins that deviate significantly 
    // from the average fill level to maintain homogeneity in bin usage.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

