    }

    // New Bin Logic: If the bin is currently empty (bin_residual == bin_capacity),
    // calculate a cost to open it based on the current mean_residual. 
    // Opening a new bin is penalized unless the open bins are already very full.
    if bin_residual == bin_capacity {
        score = 60.0 + (mean_residual * 0.5);
    }

    // Harmonic-like weight: favor bins that result in a post_residual that is a 
