    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits (Best-Fit principle).
    // If post_residual is small, it's a good fit.

    // 2. Lookahead logic: If the next item fits into the current post_residual, 
    // heavily reward this bin to keep the next item packed tightly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
        // Reward cases where the remaining space is almost perfectly consumed
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Prevent fragmentation: If post_residual is too small to fit common items 
    // (e.g., < 10), it becomes "dead space". Penalize this.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global state awareness: If we are near the end of the stream, 
    // prioritize closing bins (lower mean_residual) to avoid leaving many half-empty bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (mean_residual - post_residual as f64) * 0.2;
    }

    // 5. New Bin Logic: Discourage opening a new bin unless the current options are very poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current fit quality is generally poor across the board
        score += 35.0 + (open_bins_count as f64 * 0.1);
    }

    // 6. Last Chance Penalty: If this is the only bin that can fit the item, 
    // we should prioritize it unless it's a terrible fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
