pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it prevents larger items from fitting later. 
    // We penalize values in the [1, 15] range quadratically.
    if post_residual > 0 && post_residual < 16 {
        score += (16.0 - post_res).powi(2) * 0.5;
    }

    // Lookahead coupling: If the next item is large, prioritize keeping 
    // the current bin's post_residual large enough to accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_res) * 2.5;
        }
    }

    // Progression coupling: As the stream nears the end, become more aggressive 
    // about filling bins (Best Fit) rather than opening new ones.
    // At the start, we are more tolerant of creating small gaps.
    score += (1.0 - progress) * (post_res * 0.2);

    // New Bin Penalty: If this is an empty bin, add a significant constant 
    // baseline to force the algorithm to prefer existing bins unless the 
    // current fits are extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 20.0);
    }

    // Scarcity adjustment: If we have very few bins that can fit this item, 
    // prioritize using them to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mean residual balance: If the current bin is significantly "emptier" 
    // than the average bin, penalize it to encourage uniform filling.
    if (bin_residual as f64) > (mean_residual * 1.2) {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic-inspired residual optimization.
    // Goal: Minimize post_residual, but penalize "near-miss" space that cannot fit common item sizes.
    // We prioritize bins that result in high utilization (low post_residual) 
    // while using lookahead to avoid creating 'dead zones' for the next item.

    let mut score = post_residual as f64;

    // 1. Penalty for creating a bin that is too small for the next item if it's large.
    // If post_residual is small but > 0, it creates a "sliver" that is useless.
    if post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 2. Harmonic clustering: Favor bins that leave residues matching common item divisors (e.g., 20, 25, 33).
    // This attempts to keep the residual space "useful" for future items.
    let harmonic_penalty = if post_residual > 0 {
        let rem = post_residual % 20;
        (rem as f64).min((20 - rem) as f64)
    } else {
        -5.0 // Strong reward for perfect fit
    };
    score += harmonic_penalty;

    // 3. Last chance logic: If this is the only bin that fits, we are forced to take it.
    // But if we are considering a new bin, we penalize it based on how many bins are already open.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to existing open bins and progress.
        let progress = step_index as f64 / total_items as f64;
        score += (open_bins_count as f64 * 2.0) + (progress * 10.0);
    } else {
        // Reward for using existing bins, specifically those with residuals close to the mean.
        let dev_from_mean = (bin_residual as f64 - mean_residual).abs();
        score -= dev_from_mean * 0.1;
    }

    // 4. Lookahead coupling: If next_item_size is large, prioritize bins with higher current residuals.
    if next_item_size > 60 {
        score -= bin_residual as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
