        // Reward placements that leave a residual close to the expected next item size
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score += diff * 0.5;
        }

        // Penalize creating "dead zones" (small residuals that cannot fit common items)
        // Given item range, residuals < 10 are generally unusable
        if post_residual > 0 && post_residual < 10 {
