pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1..10) that are unlikely to be filled.
    // We reward post_residual values near 0 (perfect fit) or larger values 
    // that leave room for future items.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Factor in lookahead: if the next item is large, favor larger residuals.
    // If the next item is small, favor tighter fits.
    let lookahead_mod = if next_item_size > 0 {
        (next_item_size as f64 - post) * (1.0 - progress)
    } else {
        0.0
    };

    // If this is the last chance to fit in an existing bin, reduce penalty for poor fit.
    let desperation_factor = if fitting_bins_count == 1 { -20.0 } else { 0.0 };

    // Base score: punish high post_residual, but weight it by progress.
    // As the stream nears the end, prioritize filling bins completely.
    let mut score = post + (post * post * 0.05) + dead_space_penalty + lookahead_mod + desperation_factor;

    // Discourage opening a new bin unless the current options are very poor.
    if bin_residual == bin_capacity {
        score += 15.0 + (progress * 20.0);
    }

