    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalize opening new bins heavily, but decrease penalty as we reach the end of the stream
    // to allow for better packing density in the final stages.
    if is_new_bin {
        score += (bin_capacity as f64) * (1.5 - progress);

        // If we have many open bins, opening a new one is generally bad unless residuals are very poor
        score += open_bins_count as f64 * 2.0;
    } else {
        // Reward fitting into bins that align with the mean residual to keep bins uniform
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.5;

        // If this is the only bin that can fit the item, prioritize it strongly
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Lookahead heuristic: If the next item exists, favor placements that leave enough room
        // for the next item (Best Fit Decreasing style logic)
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0; // Reward placement that allows next item to fit
            } else {
                score += 5.0;  // Penalize placement that forces a new bin for the next item
            }
        }
    }

    // Apply a non-linear penalty for creating "dead space" (very small residuals)
    // that are unlikely to be filled by future items (assuming distribution mean ~50)
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (minimize post_residual)
    // We prioritize bins that result in smaller residuals (tighter packing).

    // 2. Penalty for "Dead Space" (Harmonic Thresholding)
    // Residuals in the range [1, 9] are extremely dangerous as they can only fit very small items.
    // If post_residual is in this range, we penalize it heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead Sensitivity (Harmonic Coupling)
    // If we have a next_item_size, we prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item perfectly
            score -= (bin_capacity - post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Penalize bins that block the next item if we have other options
            score += 15.0;
        }
    }

    // 4. Mean Residual Balancing
    // Avoid creating bins that are significantly worse than the current average.
    if post_residual as f64 > mean_residual + 10.0 {
        score += 20.0;
    }

    // 5. Threshold for opening a new bin
    // If we are forced to open a new bin, we only do so if the current best existing bin
    // creates a "bad" fit (post_residual < 10).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if existing bins are all "bad" fits
            score += 35.0;
        } else {
            // No choice, must open
            score -= 50.0;
        }
    }

    // 6. Progressive tightening
    // As the stream progresses, prioritize closing bins (minimizing open_bins_count)
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the range (0, 10), it is highly likely
    // to become unusable dead space (since min item size is usually > 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bin Pressure: Penalize opening new bins when existing bins could suffice.
    // If this is a new bin (bin_residual == bin_capacity) and other bins can fit the item,
    // apply a significant penalty to discourage premature bin expansion.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Synergy: If next_item_size is known, favor bins that leave enough space
    // to accommodate the next item perfectly (Best Fit for the pair).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap_after_next = post_residual - next_item_size;
            if gap_after_next == 0 {
                score -= 40.0; // Perfect packing for next item
            } else if gap_after_next < 10 {
                score += 20.0; // Creating a bad gap for the next step
            }
        }
    }

    // 4. Global Efficiency: Reward filling bins that are already "half-empty" to consolidate
    // space usage, weighted by the progression of the stream.
    let progress = step_index as f64 / total_items as f64;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
