            score += (fitting_bins_count as f64) * 50.0;
            // Also penalize if the mean residual is high (meaning existing bins are quite empty).
            score += mean_residual * 0.5;
        }
    }

    // 6. Dynamic balance: If fitting_bins_count is 1, this bin is the only option.
    // We should favor this bin to avoid opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity)
    // We want to force usage of existing bins, especially early in the stream.
    let new_bin_penalty = if bin_residual == bin_capacity { 
        45.0 + (30.0 * progress) 
    } else { 
        0.0 
    };

    // Calculate a "fit tightness" factor: smaller post_residual is generally better (Best Fit).
    // We apply a non-linear penalty for larger post_residuals to avoid fragmented space.
    let tightness_score = post.powf(1.5);

    // Lookahead logic: If the next item is large, prioritize leaving enough room for it.
    // If the current post_residual is smaller than the next_item_size, it's a "bad" placement 
    // because it effectively traps the current bin's remaining space.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post) * 2.5
    } else {
        0.0
    };

    // Interaction with global state: penalize creating a new bin if we have many bins open already.
    let fragmentation_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64).sqrt() * 5.0
    } else {
        0.0
    };

    // Combine factors
    // We subtract the number of fitting bins to reward putting items into bins that are 
    // "nearly full" or specific to this item size, favoring consolidation.
    let score = tightness_score + new_bin_penalty + lookahead_penalty + fragmentation_penalty 
                - (fitting_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
