            score += (mean_residual * 2.0) + (fitting_bins_count as f64 * 10.0);
        }
    }

    // 4. Density Balancing: If we are deep in the stream, favor utilizing existing bins 
    // to minimize total_bins count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // 5. Fragmentation Avoidance: Penalize leaving a sliver of space that is too small for common items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: favor smaller post-residuals (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": residuals that are too small to fit common items
    // If post_residual is < 10, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item fits in this post_residual, prioritize this bin heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // Global state awareness: If we have many open bins, penalize opening a new one
    if is_new_bin {
        score += 20.0 + (open_bins_count as f64 * 2.0);
    } else {
        // If this is the only bin that fits, reward it to avoid opening a new bin unnecessarily
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Dynamic horizon: as we approach the end of the stream, prioritize space consolidation
    if progress > 0.8 {
        score += (mean_residual - post_residual as f64).abs() * 0.5;
    }

    // Penalize large residuals that deviate significantly from the mean
    if !is_new_bin {
        score += (post_residual as f64 - mean_residual).powi(2) * 0.01;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let res_sq = post_res * post_res;

    // Penalize small residuals (dead space) more heavily early in the stream
    // to encourage tighter packing while the stream has high entropy.
    // As the stream progresses, favor packing that leaves space for future items.
    let dead_space_penalty = (1.0 - progress) * (100.0 - post_res).powi(2);

    // Encourage filling bins that are already "near" the average fullness
    // to minimize the variance of residuals across open bins.
    let variance_penalty = (post_res - mean_residual).abs() * 0.5;

    // Lookahead logic: if next_item_size is large, avoid leaving a residual
    // smaller than that size, as it creates "orphaned" space.
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
        (next_item_size as f64 - post_res) * 2.0
    } else {
        0.0
    };

    // New bin logic: if we have many fitting bins, heavily penalize opening a new one.
    // If we have very few, relax the penalty to allow for better future fits.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (fitting_bins_count as f64 * 50.0) + (progress * 100.0)
    } else {
        0.0
    };

    // Base score is the post_residual itself (Best Fit variant).
    // Subtracting the lookahead and variance components to favor better state alignment.
    let mut score = res_sq + dead_space_penalty + variance_penalty + lookahead_penalty + new_bin_penalty;

    // Favor bins that are more "congested" (smaller post_residual) 
    // to keep the number of open bins minimized.
    score -= (1.0 - progress) * post_res;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common items).
    // If post_residual is < 10, it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic preference: Reward residuals that are multiples of common item sizes (e.g., 20, 25).
    // This helps align future items into current bins.
    if post_residual % 25 == 0 {
        score -= 15.0;
    } else if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 3. Lookahead Logic: If next_item_size fits in the post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
