    // 5. New Bin Threshold: If bin_residual == bin_capacity (New Bin candidate),
    // only choose it if the current best fit would leave a highly fragmented residual.
    if bin_residual == bin_capacity {
        // High baseline to prevent opening new bins prematurely.
        score = 60.0;
        // If we have many open bins, penalize opening more.
        score += (open_bins_count as f64) * 5.0;
    }

    // 6. If this is the last chance for this item (fitting_bins_count == 1),
    // we should prioritize taking it to avoid opening a new bin later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
