        // Penalize opening a new bin based on how much room is left in existing bins.
        // Higher mean_residual means we have plenty of space elsewhere, so opening a new bin is bad.
        score += mean_residual * 2.5;

        // If the current item is small, opening a new bin is usually a waste.
        score += (item_size as f64) * 0.5;
