        let fit_margin = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_margin * 0.5);
    }

    // 3. Prevent "Last Chance" wastage: If this is the only bin that fits, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. Tightness bias: Prefer bins that become very tight (post_residual -> 0).
    // This is already partially captured by the base score, but we penalize medium-sized residuals
    // to force a "Best Fit" behavior.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // Strong reward for near-full bins
    }

    // 5. Progress normalization: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
