pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best-Fit (smaller post_residual is better)
    let mut score = post;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often better to have filled it completely. 
    // We penalize values that are "almost" full but leave unusable slivers (e.g., 1-9).
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If a future item exists, prefer bins that accommodate it.
    // If the next item fits into the post_residual, we reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        } else {
            // If it doesn't fit, penalize based on how much it misses by,
            // scaling by progress to become more conservative near the end of the stream.
            score += (next_item_size as f64 - post) * (0.5 + 0.5 * progress);
