}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic Best-Fit with Lookahead Penalty
    // Objective: Minimize post_residual, but prioritize bins that leave space 
    // for the next_item_size or align with harmonic divisions (e.g., 1/2, 1/3 capacity).

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for creating "orphan" space that cannot fit common items (< 10)
    // If post_residual is small but > 0, it's often wasted space.
    if post_residual > 0 && post_residual < 10 {
