    // These fractions are often optimal for packing future items.
    let harmonic_dist = (post_residual as f64 % 25.0).min(25.0 - (post_residual as f64 % 25.0));
    score += harmonic_dist * 0.5;

    // 4. Density management: If many bins are open, penalize opening a new bin (bin_residual == capacity)
    if bin_residual == bin_capacity {
