    if !is_new_bin && fitting_bins_count == 1 {
        score -= 100.0;
    }

    // 5. Dynamic Time Horizon:
    // As we near the end of the stream, prioritize aggressive space utilization
    // to minimize the final bin count.
    score -= (progress * 20.0);

