        // Harmonic refinement: if the fit is "tight" (leaving < 10 space), reward more.
        if (post_residual - next_item_size) < 10 {
            score -= 15.0;
        }
    }

    // 3. Prevent opening a new bin if an existing bin is a "good" fit.
    // If bin_residual == bin_capacity, we are considering opening a new bin.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin if there are other bins that could fit the item.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
        // Penalty based on the current mean_residual: don't open new bins if existing ones are empty.
        score += mean_residual * 0.5;
    }

    // 4. Harmonic thresholding:
    // If post_residual is in a range that makes it hard to pack future items (e.g., 1-9),
    // penalize heavily unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, be more aggressive with packing (lower score).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

