    // 4. Mean Residual Balancing: Favor bins that keep the overall mean residual stable,
    // preventing the accumulation of highly fragmented bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it 
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
