    // but allow flexibility as the stream nears completion.
    let emptiness_penalty = (1.0 - res_ratio).powf(2.0) * 100.0 * (1.0 - progress);
    score += emptiness_penalty;

    // Lookahead logic: If the next item fits into the current post_residual,
    // heavily reward this bin to keep the packing tight.
    if next_item_size > 0 && next_item_size <= post_residual {
