    }

    // If considering a new bin (bin_residual == bin_capacity):
    // Penalty is scaled by progress to discourage opening new bins as the stream nears the end.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 30.0);
    }

    score
