    // We penalize residuals between 1 and 9 significantly.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // reward this bin to keep the packing tight.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic thresholding: As the stream progresses, prioritize closing bins 
    // to reduce the number of open bins (fragmentation management).
    let open_penalty = (open_bins_count as f64) * progress * 2.0;
    score += open_penalty;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy 
    // baseline cost to avoid opening new bins unless the fit is poor elsewhere.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already high
        // or if we are late in the stream and need to clear space.
        score += 35.0 - (mean_residual * 0.2);
    } else {
        // If it's an existing bin, reward it if it's the only one that fits the item.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Non-linear coupling: penalize high residual variance as we reach the end of the stream.
    score += (post / bin_capacity as f64) * progress * 15.0;

    score
}

