pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (Best Fit).
    // The base score is post_residual, which naturally favors filling bins tightly.

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, 
    // heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;

        // Bonus for creating an even tighter fit for the next item (minimizing waste)
        let waste_after_next = (post_residual - next_item_size) as f64;
        score -= (100.0 - waste_after_next) * 0.1;
    }

    // 3. Penalty for "orphaning": If we are in the last fitting bin, 
    // avoid opening a new bin unless the current fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 4. Mean Residual Balancing: Penalize deviations from the mean residual 
    // to keep bins balanced in terms of remaining capacity.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. New Bin Thresholding: If considering a new bin (bin_residual == capacity),
    // apply a high cost to prevent opening new bins prematurely.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Threshold based on progress: be more conservative later in the stream.
            let progress = step_index as f64 / total_items as f64;
            score += 45.0 + (progress * 20.0);
        }
    } else {
        // 6. Penalty for creating "dead space": bins that result in small, 
        // unusable remainders (e.g., < 10) are usually bad unless it's a perfect fit.
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }
