    // If we have many open bins, we want to consolidate (prefer smaller residuals).
    // If we have few, we can afford to be more "picky" to save space for later.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // 4. Handle the "New Bin" logic:
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very high (we have lots of space elsewhere)
