    // because it makes future fitting harder in specific distributions.
    if post_residual % 10 != 0 {
        score += 5.0;
    }

    // 6. Mean-reversion: If this bin's residual will be significantly below the mean, 
    // it's a good place to put the item to "tighten" the packing.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items 
    // but large enough to waste capacity. If the post_residual is between 1 and 9, 
    // it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless no other bins can accommodate the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Necessary evil: opening a new bin is the only option
        }
    }

    // 4. Global Efficiency: If the current bin's residual is significantly lower than 
    // the mean residual of other bins, it's a "tight" bin. We favor filling tight bins 
    // to keep them from becoming "stragglers" later.
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // 5. Progression Scaling: As the stream nears the end, prioritize closing bins
    // by preferring tighter fits (lower post_residual) to minimize straggling items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating unusable space (Best Fit variant)
    // Minimizing post_residual is the standard Best Fit approach.
    score = post_residual as f64;

    // 2. Aggressive Lookahead Matching:
    // If we have a next item, we want to prioritize bins where the post_residual
    // can accommodate the next item (trying to pair items).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: significantly lower the score if the bin can take the next item
            score -= 45.0;
        } else {
            // Penalty: if the post_residual is small but > 0, it's "stranded" space
            // that cannot fit the next item.
            score += (post_residual as f64) * 0.5;
        }
    }

    // 3. Pressure Management:
    // If we are late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress.
        // Early on, we are more willing to open bins.
        score += 30.0 + (progress * 40.0);
    }

    // 4. Global Optimization:
    // If this is the last chance to fit the item (fitting_bins_count == 1),
    // reduce the penalty for a poor fit to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Balance with Mean Residual:
    // Prefer bins that are closer to the current average fullness.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a "fragment" bin that is hard to fill later
    // If the post-residual is small but not zero, it's often a "dead space" trap
    if post_residual > 0 && post_residual < 20 {
        score += 15.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // Lookahead logic: if the next item fits into the current post_residual, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
