        score += new_bin_penalty;
    }

    // Global state awareness: 
    // If we have many open bins, penalize opening another one heavily.
    // If we have few open bins, we can afford to be more selective.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).sqrt() * 5.0;
    }

    // Adjust for the "last chance" scenario
    // If this is the only bin that fits the item, make it very attractive (discount)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Favor bins that are closer to the mean residual to keep packing density uniform
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) more heavily as the stream progresses
    // to encourage tighter packing toward the end.
    let dead_space_penalty = (1.0 - (post / bin_capacity as f64)).powf(2.0 + progress * 2.0) * 100.0;

    // Reward bins that can accommodate the next item (lookahead look-up)
    // If next_item_size fits in the post_residual, reduce score.
