    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // This creates "bins" for future items.
    let harmonic_penalty = if post_residual > 0 {
        let mod_20 = (post_residual % 20) as f64;
        let mod_25 = (post_residual % 25) as f64;
        (mod_20.min(mod_25)) * 0.5
    } else {
        -5.0 // Strong reward for perfect fit
    };
    score += harmonic_penalty;

    // 3. Lookahead Optimization: If next_item_size is large, avoid leaving tiny residuals 
    // that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Penalize creating a "stranded" residual space smaller than the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if post_residual >= next_item_size {
            // Reward creating space that perfectly accommodates the next item
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.1;
        }
    }

    // 4. Thresholding/New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it unless
    // existing bins are highly fragmented (high mean_residual) or fitting_bins_count is low.
    if bin_residual == bin_capacity {
        score += 25.0; // Base cost to open a new bin
        score -= (open_bins_count as f64 * 0.2); // Discount if we already have many bins
        score -= (mean_residual * 0.1); // Discount if existing bins are mostly empty
    }

    // 5. Progression Weighting:
    // As we approach the end of the stream, be more aggressive with packing (Best-Fit).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
