    score += (progress * mean_residual) * 0.5;

    // If this is the only bin that can fit the item, discourage opening a new bin 
    // unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New bin candidate handling:
    // If bin_residual == bin_capacity, we are evaluating a brand new bin.
    // Apply a cost function that grows with open_bins_count to discourage excessive opening.
    if bin_residual == bin_capacity {
        score = 15.0 + (open_bins_count as f64 * 2.0) + (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // We prioritize bins that result in smaller post_residuals.
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class Logic: Reward residuals that match potential next item sizes
    // If the post_residual is close to the next_item_size, we reward this placement
    // to increase the likelihood of a perfect fill in the next step.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 20.0 * (1.0 / (1.0 + diff));
    }

    // 3. Fragmentation Control: Penalize bins that create small unusable slivers
    // A post_residual < 10 is often "dead space" because min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Lookahead/Density Balancing:
    // If we have many open bins, penalize opening a new one significantly.
    if bin_residual == bin_capacity {
