    // 5. Efficiency Scaling:
    // As the stream progresses, tighten the requirements for opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Fitting Constraint:
    // Heavily penalize if this is the only bin that can fit the item, 
    // but the resulting post_residual is highly inefficient.
    if fitting_bins_count == 1 && post_residual > 20 {
