        }
    }

    // 3. Dynamic Thresholding: As we approach the end of the stream, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 4. Global State Awareness:
    // If this is the only bin that can fit the item, we are forced to use it.
    // If fitting_bins_count is high, we can afford to be more selective.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64) * 2.0;
    }

    // 5. New Bin Logic:
    // If bin_residual == bin_capacity, this is a new bin. 
    // We only want to open a new bin if the existing fits are all "bad" (high residuals).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
