    // 2. Lookahead Coupling: Reward bins that fit the next item perfectly (post_residual == next_item_size)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Cannot fit next item, penalize proportionally to the gap
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // 3. New Bin Thresholding: 
    // If this is a new bin, penalize it unless fitting_bins_count is low or post_residual is very efficient
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Forced to open
        } else {
            // Only open new if the current mean_residual is already very tight (high utilization)
            score += (100.0 - mean_residual) * 2.0;
        }
    }

    // 4. Tightness bias: 
    // If post_residual is very small (near 0), it's a good fit, reward it.
    if post_residual < 5 {
        score -= 25.0;
    }

    // 5. Progression adjustment: 
    // As we near the end of the stream, prioritize clearing existing bins (lower score for existing)
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

