    // If we have many open bins, penalize opening a new one.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // If this is the last chance for this item, prioritize fitting it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Heuristic coupling: favor bins that keep the mean residual balanced.
    // If the current bin's post_residual is close to the mean, it's a stable fit.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space: we prefer smaller post-fit residuals (Best Fit).
    // However, we penalize very small residuals (e.g., < 5) late in the stream to avoid fragmentation.
    let fragmentation_penalty = if post_res < 5.0 && post_res > 0.0 {
        (1.0 - progress) * 20.0
    } else {
        0.0
    };

    // Lookahead logic: If the next item is large and won't fit in the remaining space, 
    // we should prioritize bins that have enough space for the next item.
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
        (next_item_size as f64 - post_res) * 0.5
    } else {
        0.0
    };

    // Global state awareness: Reward using existing bins early, but become 
    // more aggressive about bin consolidation as the stream progresses.
    let efficiency_bias = (open_bins_count as f64 / 10.0) * progress;

    // New bin logic: If this is a new bin (post_residual == bin_capacity - item_size),
    // apply a penalty that scales with progress to force consolidation.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        35.0 + (progress * 40.0)
    } else {
        0.0
    };

    // Coupling: Combine post_residual with the mean_residual to favor bins 
    // that align with the average state of the system, promoting uniform filling.
    let deviation_penalty = (post_res - mean_residual).abs() * 0.2;

    post_res + fragmentation_penalty + lookahead_penalty + new_bin_penalty + deviation_penalty - efficiency_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
