    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless the existing fitting_bins_count is low
        // and the open bins are already cluttered.
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Harmonic Density: Favor bins that keep the mean_residual low 
