pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual to fill bins tightly, but penalize small, unusable gaps.
    // A gap < 10 is considered "dead space" because min item size is 10.

    let mut score = post_residual as f64;

    // Penalty for creating "dead space": if post_residual < 10 and > 0, it's likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // Encourage using existing bins over opening new ones unless the new bin is highly efficient.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. Penalize it based on how many bins are already open.
        // As open_bins_count grows, we become more desperate to fit items into existing bins.
        score += (open_bins_count as f64) * 5.0;

        // If we have many fitting bins, opening a new one is almost always a bad move.
        score += (fitting_bins_count as f64) * 20.0;
    } else {
        // Within existing bins, favor bins where the residual stays close to the mean.
        // This keeps the "load" balanced across bins.
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    // Lookahead: If the next item exists, penalize placements that make it impossible to fit.
    if next_item_size > 0 {
        if post_residual < next_item_size {
