    }

    // 4. Fragmentation Control: Penalize bins that deviate significantly from the mean_residual.
    // We want to keep residuals uniform across bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Last Chance Logic: If this is the only bin that can fit the item,
    // take it unless it results in an extremely poor fit (> 50).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < 50 {
            score -= 50.0;
