    // Dynamic constraint: discourage opening new bins (bin_residual == bin_capacity)
    // as the stream progresses, unless the fit is extremely poor.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0 * (1.0 - progress);
