    // 4. Tightness Calibration: Reward placements that leave a residual close to the mean_residual
    // to keep bin utilization balanced across the set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Last Chance Logic: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals.
    // We want the post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead optimization: If the next item fits into the post_residual, 
    // reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
        // Reward creating a "tight" remaining space after the next item
        score += ((post_residual - next_item_size) as f64) * 0.5;
    }

    // 3. Penalty for fragmentation: If the post_residual is too small to fit 
    // common items but too large to be ignored, penalize it.
    if post_residual > 0 && post_residual < 15 {
        score += 20.0;
    }

    // 4. Strategic new bin control: 
    // If this is a new bin (bin_residual == bin_capacity), only choose it if 
    // the current fitting bins are very poor (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty to prevent opening a new bin unless necessary
            score += 65.0;
        }
    } else {
        // If it's an existing bin, reward it based on how much it aligns 
        // with the current average density (mean_residual).
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base penalty for creating "dead zones" (small residuals that are hard to fill)
    // We prioritize bins where the post_residual is either 0 or large enough to fit the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead utility: If next_item_size fits in the post_residual, reduce score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global state: Penalize opening new bins early in the stream, 
    // but allow flexibility if the current fit is extremely poor (Best Fit style).
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Only pick if we have exhausted good options or are near the end of the stream.
        score += 35.0 + (1.0 - progress) * 20.0;
    } else {
        // If this is the only bin that fits the item, make it very attractive.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // Dynamic thresholding: If the current bin is significantly tighter than the mean, 
        // it's a good place to pack to conserve "loose" bins for larger items later.
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 4. Density preservation: Penalize bins that would end up with very small capacity left
    // unless that capacity is exactly zero.
    if post_residual > 0 && post_residual <= 5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement.
    // Minimizing this naturally pushes towards Best-Fit behavior.
    let mut score = post_res;

    // Penalty for creating 'dead space' that is likely too small for future items.
    // We define 'dead' as space < 10 (the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 + progress);
    }

    // Lookahead logic: If the next item doesn't fit in the remaining space, 
    // penalize this placement to favor bins that leave room for the successor.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 25.0 * (1.0 - progress);
    }

    // New Bin Logic: Only open a new bin if the current fit is poor or forced.
    // If bin_residual == bin_capacity, we are evaluating the "Open New Bin" option.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early in the stream, 
        // but lower the penalty as the stream progresses to allow packing efficiency.
        score += 35.0 * (1.0 - progress);

        // If there are many fitting bins, opening a new one is almost always bad.
        score += (fitting_bins_count as f64) * 15.0;
    } else {
        // Reward bins that balance the load (keeping residual close to mean_residual).
        // This encourages uniform bin usage.
        let deviation = (post_res - mean_residual).abs();
        score += 0.5 * deviation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual
    // 2. Penalty for creating "dead space" that cannot fit common items
    // If post_residual is small but > 0, it might be unusable for future items.
    if post_residual > 0 && post_residual < 10 {
