            score += 25.0;
        }
    }

    // 4. Harmonic/Modular balance:
    // Avoid leaving remainders that are awkward multiples (e.g., 20-30 range)
    let rem = post_residual % 25;
    if rem < 5 {
        score -= 10.0;
    }

    // 5. Global state normalization:
    // If we have many open bins, prioritize tightening the most empty ones
    if open_bins_count > 5 {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // 6. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), make it expensive
    // unless all other options are very poor fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty for opening a new bin if an existing one works
            score += 65.0;
        } else {
            // No other choice
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
