    // 4. Fitting Pressure: If this is the last chance for the current item, lower the cost to prevent a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 200.0;
    }

    // 5. Global Efficiency: If the current bin is becoming very sparse, discourage it to prevent scattered items.
    if post_residual > 70 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
