        score += (open_bins_count as f64) * 2.0;
    }

    // 4. Dead-space avoidance: If the post_residual is too small to fit any likely future item
    // (e.g., < 10), it becomes "fragmentation." Penalize this unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 5. Global State: If the average residual of open bins is high, prefer filling 
    // existing bins to consolidate space rather than opening new ones.
    if !is_new_bin && mean_residual > 20.0 {
        score -= 30.0;
    }

    // 6. Scarcity: If this is the only bin that can fit the item, prioritize it.
