    let mut score = post_residual as f64;

    // Penalty for creating a bin with a residual that is too small for any future items (dead space).
    // If post_residual < 10, it's essentially wasted space.
    if !is_new_bin && post_residual < 10 && post_residual > 0 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // Lookahead logic: if the next item is large, prioritize keeping space available.
    if next_item_size > 0 {
        if post_residual < next_item_size {
