    // Dynamic pressure: As the stream progresses, favor packing tighter to avoid 
    // fragmenting space late in the process.
    let tightness_factor = (mean_residual / bin_capacity as f64) * 20.0;
    score += tightness_factor * progress;

    // Penalty for opening a new bin:
    // We only open a new bin if the score of the new bin is lower than existing ones.
    // We scale this penalty by the number of open bins and the progress to prevent 
    // excessive bin creation early on.
    if is_new_bin {
        let open_bin_penalty = (open_bins_count as f64).powf(1.5) * (1.0 - progress * 0.5);
        score += 35.0 + open_bin_penalty;
    }

    // If this is the last chance to fit an item into an existing bin, reduce the penalty 
    // for poor fits to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

