    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item size clusters
    // This helps align residuals with potential future items (e.g., 20, 25, 33, 50)
    if post_residual > 0 {
        let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
        score += harmonic_penalty * 0.8;
    }

