            score += 35.0 + (mean_residual * 0.5);
        }
    } else {
        // 4. Best Fit Decreasing logic: 
        // Prefer bins that become very tight (Best Fit)
        score += (post_residual as f64) * 0.1;

        // 5. If this is the last chance for the current item to fit in an existing bin,
        // reward it slightly to prevent unnecessary bin creation.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 6. Global density pressure: 
    // As we approach the end of the stream, prioritize closing bins (lower residuals).
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res.powf(1.5);

    // Penalize opening new bins early in the stream, but allow it if it creates a better fit later
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is scaled by remaining stream and current bin count
        // We want to avoid new bins if we have many existing bins or if the stream is ending
        score += (1.0 - progress) * (open_bins_count as f64 * 15.0) + (mean_residual * 0.5);
    } else {
        // Reward placing in a bin that leaves room for the next known item (lookahead coupling)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64) * 1.2;
        }

        // Penalize bins that become "dead space" (e.g., leaving a tiny sliver that fits nothing)
        // If the post_residual is < 10 (smallest possible item size), it's likely dead space.
        if post_residual < 10 {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Coupling: If this is the only bin that fits, heavily favor it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Normalize against mean_residual to keep scores relative to current density
    score += (post_res - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

