            score -= (50.0 - gap as f64).max(0.0);
        } else {
            // Penalize if this placement prevents the next item from fitting here
            score += 15.0;
        }
    }

    // 3. Pressure management: If we are nearing the end of the stream, 
    // prioritize closing bins (lower residual) over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. Global balance: Prefer using bins that are already "fuller" (Best-Fit principle).
    // Compare post_residual against the mean_residual of all open bins.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. New Bin Penalty: Make opening a new bin expensive unless the fit is perfect.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the item is large or if we have very few open bins.
        score += 45.0 + (item_size as f64 * 0.5);
    }

    // 6. Force efficiency if this is the last chance for this bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
