    if residual > mean_residual {
        score += (residual - mean_residual) * 0.5;
    }

    // If this is the only bin that can fit the item, reward it to prevent 
    // unnecessary new bin creation (unless the fit is extremely poor).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
