        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other viable options.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 2.5);
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Balance: Penalize bins that deviate significantly from the mean residual
    // to encourage uniform packing and maximize potential for future large items.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 6. Final progression weight: As the stream nears completion, become more aggressive
    // about filling existing bins to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
