    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // 2. Lookahead Coupling:
    // If the next item cannot fit into the resulting post_residual, we penalize this placement
    // more heavily if the current fitting_bins_count is low (i.e., we are exhausting options).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 / (fitting_bins_count as f64 + 0.1));
    }

    // 3. Global State Balancing:
    // If this bin's post_residual is significantly lower than the mean_residual of other bins,
    // it suggests this bin is becoming "tight". We prefer filling tighter bins first (Best Fit).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 4. New Bin Thresholding:
    // If the bin is empty (new bin candidate), we only pick it if the score is very competitive.
    // We add a "tax" for opening a new bin that scales with the number of open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Harmonic Modulo Smoothing:
    // Favor residuals that are multiples of common item sizes (e.g., 20, 25, 50).
    if post_residual % 25 == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

