    let mut score = post_residual as f64;

    // Dead space penalty: If post_residual is small (e.g., < 10), it is likely unusable for 
    // future items (min size 10). We penalize this heavily to avoid fragmentation.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
