        score += (progress * 20.0);
    } else {
        // If it's an existing bin, reward it if it's the only one that fits the item 
        // to prevent unnecessary overflow into new bins.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Balance against the average residual: Avoid bins that deviate too far from 
    // the mean state of the system to maintain uniform packing.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // However, if the post_residual is exactly 0, we reward it heavily as an "ideal" fit.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead Matching: If the post_residual can perfectly accommodate the next_item, 
    // prioritize this bin to prevent fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Mean Residual Balancing: If the current bin's post_residual is significantly 
    // worse than the average, penalize it to encourage uniform bin usage.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // 4. Scarcity/Closing Logic: If fitting_bins_count is 1, this is our only chance to 
    // pack without opening a new bin. Heavily reward staying in this bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // 5. Empty Bin Thresholding: If this is a new bin (bin_residual == bin_capacity), 
    // add a high cost to opening it unless the existing options are extremely poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if the existing options are very fragmented (mean_residual < 20).
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 60.0;
        } else {
            score += 30.0;
        }
    }

    // 6. Progressive Tightening: As the stream nears the end (step_index / total_items), 
    // become more aggressive about filling existing bins to reduce bin count.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
