    // heavily reward this bin to keep clusters tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // Dynamic pressure: as the stream progresses, increase penalty for opening new bins.
    // We normalize the influence of open_bins_count against the stream progress.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. Penalize based on progress and current open bin count.
        // As the process nears completion (progress -> 1.0), penalize new bins more harshly.
        score += 20.0 + (progress * 50.0) + (open_bins_count as f64 * 2.0);
    } else {
        // If this bin is the last chance for the current item, reward it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Coupling: Penalize residuals that deviate significantly from the global mean residual.
        // This promotes uniform filling across all open bins.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Non-linear penalty for creating very small gaps that are unlikely to fit future items (<= 5).
    if post_residual > 0 && post_residual <= 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": residuals that are smaller than the smallest likely item (e.g., < 10)
    // but larger than zero are generally difficult to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Harmonic heuristic: prioritize bins where the post_residual is a multiple of the next_item_size
    // This attempts to create "perfect" subsequent fits.
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        if remainder == 0 {
            score -= 15.0; // Strong reward for alignment
        } else {
            score += (remainder as f64) * 0.2;
        }
    }

    // Progression logic: as we approach the end of the stream, prioritize closing bins
    // by preferring smaller residuals (Best Fit behavior).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // open bins are available. We only want to open a new bin if the existing ones
    // are "too full" to accept the next item effectively.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to encourage packing into existing ones.
        score += 45.0;

        // If many bins are already open, opening another is costly.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // If the bin is already open, reward it if it's the only one that fits the current item
        // to prevent fragmenting space across too many bins.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Favor bins that maintain the mean residual balance to keep packings uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual if it's small but larger than 0,
    // as these gaps (1-9) are notoriously hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual,
    // heavily reward this bin to minimize future bin openings.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if we have existing capacity.
    // If this is a new bin (bin_residual == bin_capacity) and other bins could fit it,
    // apply a significant penalty to encourage Best Fit behavior.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 75.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Global Packing Efficiency: If this bin is already quite full,
    // reward placing items here to consolidate space.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // 5. Progression Weighting: As we approach the end of the stream,
    // be more conservative with bin openings.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (Best Fit).
    // The base score is already post_residual.

    // 2. Lookahead mechanism:
    // If next_item_size fits perfectly into post_residual, reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (100.0 - (post_residual - next_item_size) as f64) * 0.5;
    }

    // 3. Penalty for "New Bin" creation:
    // If this is an empty bin, penalize it unless fitting_bins_count is 0.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 85.0;
    }

    // 4. Fragmentation avoidance:
    // Penalize small residuals that are unlikely to fit future items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 5. Mean-Residual alignment:
    // Prefer bins that stay close to the current mean_residual to keep packing density uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    // 6. Progress-based scaling:
    // As we approach the end of the stream, prioritize closing bins over spreading items.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score (Best-Fit Decreasing intuition combined with lookahead)
    // 1. Base Score: The post_residual is the primary target (Best-Fit strategy).
    // Smaller post_residual is better, so we use it as the base.
    let mut score = post_residual as f64;

    // 2. Lookahead Logic: If the next item fits into the current post_residual, 
    // reward this placement heavily to encourage "perfect packing" of pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Fragmentation Penalty: If post_residual is small (1..9), it's often wasted space.
    // Penalize this "dead zone" unless it's a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global State Awareness: If we are near the end of the stream, 
    // be more aggressive about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && fitting_bins_count > 0 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // 5. New Bin Candidate Logic:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // We only want to open a new bin if the current fitting bins are very poor (high residuals).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if we have existing bins that can take the item.
            score += 55.0 + (mean_residual * 0.5);
        } else {
            // If no other bins fit, we must open one.
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit logic)
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often worse than having 0 residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: If next_item_size is large, penalize small post_residuals
    // because they won't accommodate the next item effectively.
    if next_item_size > 0 {
        let lookahead_penalty = (next_item_size as f64 - post_res).max(0.0) * 0.5;
        score += lookahead_penalty;
    }

    // Dynamic thresholding based on stream progress:
    // As the stream progresses, become more aggressive about filling bins (Best Fit)
    // rather than opening new ones.
    let new_bin_penalty = 15.0 + (progress * 30.0);

    // If this is a new bin candidate
    if bin_residual == bin_capacity {
        score = new_bin_penalty;
    }

    // Reward bins that bring the residual closer to the global mean (balancing)
    // This helps keep bin occupancy levels uniform.
    let mean_diff = (post_res - mean_residual).abs();
    score += mean_diff * 0.2;

    // Favor bins that have fewer alternatives (fitting_bins_count == 1)
    // to preserve capacity in bins that have more flexibility.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "sliver" space (dead space < 10 is usually unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: If the next item fits into the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Reward creating perfect fits for the next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. Packing Pressure: If only one bin can fit this item, prioritize it to avoid new bin creation
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 4. Distribution Balancing: Avoid opening new bins if the current mean_residual is high
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 100.0; // Heavily penalize opening new bins if existing ones are underutilized
        }
        // Small bias to keep new bins as a last resort
        score += 25.0;
    }

    // 5. Modulo-based "Tightness" reward: Favor bins that leave space divisible by common item sizes (e.g., 20, 25)
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize tighter fitting
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual values that create unusable gaps.
    // Gaps < 10 are almost always impossible to fill since min item_size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins if we have many bins already open.
    // This encourages filling existing bins rather than creating new ones.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    }

    // 3. Lookahead Coupling: If the next item could fit in the current post_residual,
    // we want to prioritize this bin to preserve future capacity.
    if next_item_size > 0 && post_residual >= next_item_size {
