    }

    // 4. Fitting Constraint: If this is the last chance to fit the item in an existing bin,
    // strongly incentivize choosing this bin over a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: If post_residual is exactly 0, it's a perfect fit. Reward it.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 6. Distributional Awareness: Penalize significantly above-average residuals to keep bins balanced.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // If the bin is empty (new bin candidate), we penalize it heavily unless no other bin fits the item
    // or the current bin-fill state is extremely fragmented.
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post_residual as f64;

    // 1. Reward perfect fits (Best Fit principle)
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2. Lookahead logic: If the next item fits perfectly into this post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual < next_item_size + 10 {
            // Reward "near-miss" fits for the next item to minimize fragmentation
            score -= 40.0;
        }
    }

    // 3. Penalty for fragmentation: If post_residual is small but not zero, it's often wasted space.
    // We penalize very small residuals (1-9) that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Global balance: If we have many open bins, prioritize filling existing ones to keep open_bins_count low.
    if !is_new_bin {
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // Penalty for opening a new bin: base penalty + heuristic pressure.
        score += 150.0;
        if fitting_bins_count > 0 {
            score += 200.0; // Heavily discourage new bins if existing ones can fit the item
        }
    }

    // 5. Mean-residual alignment: If this bin's post_residual is significantly better than the global mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
