}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Penalize large residuals to keep bins tight.
    let mut score = post * post / capacity;

    // Favor bins that leave room for the lookahead item (next_item_size).
    // If post_residual is slightly less than next_item_size, we penalize because 
    // it creates a "dead zone" that is hard to fill.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next && post > 0.0 {
            score += (next - post) * 2.5;
        }
    }

    // Dynamic pressure: As the stream nears the end, become more aggressive 
    // about packing into existing bins to avoid opening new ones.
    // We penalize opening a new bin (where bin_residual == bin_capacity)
    // more heavily as we progress through the stream.
    if bin_residual == bin_capacity as u32 {
        score += 15.0 * (1.0 + progress * 2.0);
    }

    // Coupling with mean_residual: If the current bin is significantly worse 
    // than the average, penalize it to force consolidation.
    if post > mean_residual {
        score += (post - mean_residual) * 0.5;
    }

    // Heuristic safety: If this is the only bin that fits, prioritize it 
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity as u32 {
        score -= 20.0;
    }

    // Non-linear penalty for creating "fragmented" small residuals 
    // that are too small to fit any likely item (e.g., < 10).
    if post < 10.0 && post > 0.0 {
        score += 12.0 * (1.0 - (post / 10.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
