    // 3. Lookahead logic: if next_item_size exists, penalize bins that leave 
    // just enough space for the current item but fail the next one.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (synergy).
            score -= 15.0;
        } else {
            // Penalize bins that would force a new bin for the next item.
            score += 5.0;
        }
    }

    // 4. Harmonic thresholding: Favor bins that leave a residual which is a multiple 
    // of common item sizes (e.g., 20, 25) to increase packing density.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. New bin avoidance: If fitting_bins_count is 1, it is our last chance to place 
    // the item in an existing bin. Heavily penalize the New Bin option.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0;
        } else {
            // If no bins fit, we must open a new one; normalize its cost.
            score = 50.0;
        }
    }

    // 6. Progressive scaling: As the stream nears the end, become more aggressive 
    // with filling existing bins to minimize the number of open bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

