pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement.
    // Lower residual (tighter fit) is generally better (Best-Fit principle).
    let mut score = post;

    // Penalty for leaving small "dead" gaps that are too small for common items.
    // If the post_residual is in the range (0, 10), it is highly likely to be wasted.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next_item_size, we penalize the bin.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 2.0;
        }
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins (lower residual)
    // to avoid leaving scattered, half-empty bins late in the process.
    let density_penalty = (open_bins_count as f64 / 10.0) * progress * 10.0;
    score += density_penalty;

    // Non-linear coupling: Heavily penalize opening new bins (bin_residual == bin_capacity)
    // unless the current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        // Only consider a new bin if the average of existing bins is already quite full.
        // If mean_residual is low, we prefer fitting in existing bins.
        score += 40.0 + (mean_residual * 0.5);
    }

    // Favor bins that are already "near full" to consolidate space.
    // Subtract based on how much of the bin is already filled.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (minimize post_residual)
    // 2. Penalty for opening new bins: Only open if forced or if existing bins are poor fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening new bin if others exist
            score += 45.0 + (open_bins_count as f64 * 0.5);
        } else {
            // Mandatory new bin
            score = 0.0;
        }
    } else {
        // 3. Harmonic/Modulo Logic: Favor residuals that are multiples of common item sizes
        // Penalize residuals that create 'dead zones' (e.g., 1-9 range)
        if post_residual < 10 {
            score += 15.0; 
        }

        // 4. Lookahead Logic: If next_item_size is large, avoid small post_residuals
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // This bin cannot hold the next item; penalize proportionally to next_item_size
                score += (next_item_size as f64) * 0.3;
            } else {
                // This bin can hold the next item; reward this capacity
                score -= (next_item_size as f64) * 0.2;
            }
        }

        // 5. Mean residual balancing: Penalize bins that deviate from the mean
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // 6. Progression scaling: As items finish, prioritize tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
