    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.45;
    }

    // 4. Mean Residual Balancing: 
    // If post_residual is significantly lower than the mean, we are creating a very tight bin.
    // This is good, but if it is too low (e.g., < 5), it might become "dead space".
    if post_residual < 8 {
        score += 12.0; 
    }

    // 5. Progression scaling: As we near the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 20.0);
    }

    // 6. Penalty for creating bins that are awkward to fill (e.g., residual between 1 and 9)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score (Best-Fit Decreasing intuition combined with lookahead)

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for creating "fragmented" small residuals (Best-Fit rule)
    // If post_residual is very small but > 0, it's often a "dead" space trap.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead mechanism: If the next item is large, avoid bins that won't fit it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize this bin if it cannot fit the *next* item
            score += 15.0 * (1.0 - progress);
        }
    }

    // 3. Global state awareness: If we are near the end of the stream, 
    // prioritize packing tighter to avoid new bins.
    if progress > 0.8 {
        // Tighten constraint: avoid new bins (bin_residual == bin_capacity)
        if bin_residual == bin_capacity {
            score += 50.0;
        }
    }

    // 4. Dynamic pressure: If few bins fit the current item, 
    // we should be more selective about which one we "waste" this capacity on.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the last chance for this item in existing bins.
        // Discount the score to prioritize filling this bin over opening a new one.
        score -= 10.0;
    }

    // 5. Balance against mean residual:
    // If this bin's residual is significantly better than the mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

