    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if is_new_bin {
        // As the stream progresses, the penalty for opening a new bin decreases 
        // to allow for better packing density in the final stages.
        score += (bin_capacity as f64 * 0.8) * (1.0 - progress.powf(0.5));

        // If there are bins that can fit the item, penalize opening a new one heavily
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Non-linear coupling: Penalize leaving small "dead" gaps that are too small 
        // for most items (e.g., < 10), scaled by the remaining stream length.
        if post_residual > 0 && post_residual < 10 {
            score += (10.0 - post_residual as f64) * (1.0 + progress);
        }

        // Lookahead heuristic: If the next item is large, avoid leaving a residual
        // that is too small for it.
        if next_item_size > post_residual && post_residual < 20 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Dynamic adjustment based on current bin state relative to the global mean.
    // Bins with higher-than-average residuals are prioritized for filling.
    let residual_delta = bin_residual as f64 - mean_residual;
    score -= residual_delta * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (small residuals that cannot hold common items)
    // We prioritize bins that leave a residual which is a multiple of 10 or 20 (harmonic alignment)
    let remainder = post_residual % 10;
    score += (remainder as f64) * 2.5;

    // 2. Lookahead synergy: if next item fits perfectly in this post_residual, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward tight fits for the upcoming item
        score -= (100.0 - diff) * 0.8;
    }

    // 3. Avoid opening new bins prematurely unless the fit is truly terrible
    if bin_residual == bin_capacity {
        // High penalty to open a new bin unless existing bins are very full
        score += 45.0 + (open_bins_count as f64 * 2.0);
        // If current bins have high mean residuals, opening a new one is less penalized
        score -= mean_residual * 0.5;
    }

    // 4. Harmonic thresholding: Favor bins that reach specific capacity milestones
    // e.g., leaving a bin with 0, 20, or 40 space is often better for future packing
    let harmonic_penalty = match post_residual {
        0 => -15.0,
        r if r % 20 == 0 => -5.0,
        r if r < 10 => 10.0, // Penalize "sliver" waste
        _ => 0.0,
    };
    score += harmonic_penalty;

    // 5. Progression scaling: As we approach the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. If this is the last chance for the current item, lower the barrier to entry
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
