    // We prefer post_residual to be as small as possible (close to 0).
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // reward this bin heavily to encourage packing pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
