    }

    // 3. Global State Awareness:
    // If we are nearing the end of the stream, be more aggressive with packing (Best Fit).
    // If we are early, be more conservative to avoid small, unusable gaps.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

