    // If bin_residual == bin_capacity, this is a new bin. 
    // Only open a new bin if the current mean_residual is very low (bins are full)
    // or if we have no other choice.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if existing bins can fit the item.
            score += 150.0 + (mean_residual * 2.0);
        } else {
            // If no bins fit, opening a new bin is mandatory.
            score -= 50.0;
        }
    }

    // 5. Fragmentation Avoidance:
    // Penalize creating tiny gaps that are unlikely to be filled (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 6. Dynamic balance:
    // Adjust score based on open_bins_count to keep total footprint low.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
