    // the mean residual of all open bins, penalize it to keep open bins balanced.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // 6. Progress Scaling: As the stream nears completion, become more aggressive
    // about closing bins by penalizing large residuals less.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want to minimize post_residual, so it is already in the score.

    // 2. Lookahead Synergy: If post_residual is close to the next_item_size,
    // we prioritize this bin to create a perfect or near-perfect fit for the next step.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward bins that leave exactly enough or slightly more than the next item
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize bins that will force a new bin for the next item
            score += 50.0;
        }
    }

    // 3. Last-Chance Mitigation: If this is the only bin that fits, we must prioritize it
    // regardless of the residual quality to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly from
    // the average usage of other bins to maintain packing density consistency.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 5. New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // apply a heavy penalty to force the algorithm to prefer any existing bin that fits.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 150.0;
        }
        // Scale new bin cost slightly by how far through the stream we are
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" that cannot fit typical items (10-30 range)
    // If post_residual is small but > 0, it's often better to have 0 than < 10.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead logic: If a future item fits perfectly in this bin, prioritize it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_gap) * 0.5;
    }

    // 3. Global state: Avoid opening new bins unless necessary.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one can fit the item
            score += 150.0 * (1.0 - progress);
        } else {
            // Necessary new bin, reward based on current capacity utilization efficiency
            score -= mean_residual * 0.2;
        }
    }

    // 4. Dynamic pressure: Tighten constraints as we approach the end of the stream.
    if fitting_bins_count == 1 && post_residual < 15 {
        // This is the last bin that can fit the item, prioritize filling it to avoid stragglers
        score -= 40.0 * progress;
    }

    // 5. Balance the mean residual to keep bins packed similarly
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post_residual (Best Fit logic)
    // We penalize larger residuals quadratically to prefer tighter packing.
    let mut score = post * post;

    // Penalty for opening a new bin:
    // If this is an empty bin (bin_residual == bin_capacity), increase cost
    // based on how many bins are already open and how much space is left globally.
    if bin_residual == bin_capacity {
        // As the stream progresses, opening a new bin becomes increasingly expensive.
        // We scale the cost by the number of open bins to encourage consolidation.
        score += (100.0 * 100.0) * (1.0 + progress) * (open_bins_count as f64).sqrt();
    }

    // Lookahead logic:
    // If the next item is large, we want to preserve bins with large post_residuals.
    // If the next item is small, we want to keep bins with small post_residuals open.
    if next_item_size > 0 {
        let lookahead_bias = (next_item_size as f64 - post) * (next_item_size as f64 - post);
        // If the current bin cannot fit the next item, we penalize the current placement 
        // if it wastes space that might have been better used by the next item.
        if (post_residual as u32) < next_item_size {
            score += lookahead_bias * 0.5;
        } else {
            score -= lookahead_bias * 0.2;
        }
    }

    // Encourage filling bins that are already closer to the mean residual
    // to keep the bin fill-levels uniform.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * (1.0 - progress);

    // If this is the last chance for this item (fitting_bins_count == 1),
    // reduce the penalty for a poor fit to ensure the item is placed.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score *= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
