    // We penalize these "slivers" unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 8 {
        score += 20.0;
    }

    // 4. Global balance:
    // Favor bins that align with the current mean_residual to keep bin states uniform.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // 5. Urgency:
    // If this is the only fitting bin, prioritize it to avoid creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

