    // 3. Balance usage across open bins: penalize bins that deviate from the mean residual.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 4. Force consolidation: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual >= item_size {
