    }

    // 5. New Bin logic: Only open a new bin if the current fit is extremely poor (large waste).
    if bin_residual == bin_capacity {
        // Only open a new bin if existing bins are mostly full (high mean residual is bad, low is good).
        // If mean_residual is low, we have space, so don't open new bins unless necessary.
        score += 45.0 + (mean_residual * 0.5);
    }

    // 6. Progressive thresholding: As we approach the end of the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
