pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Penalize gaps that are too small to fit common items (10-25)
    // If post_residual is small but > 0, it is a "fragmentation trap".
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 - (post_residual as f64 * 2.0);
    }

    // 2. Adaptive Pressure: If we have many open bins, prioritize tighter fills.
    // As open_bins_count increases, we penalize larger post_residuals more aggressively.
    score += (open_bins_count as f64) * (post_residual as f64 * 0.5);

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
