        }
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other bin fits.
    // This prevents "New Bin" from being chosen unless the existing options are very poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 10.0; // Forced to open new bin
        }
    }

    // 5. Global Efficiency: If this bin is significantly better than the mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

