    // This helps maintain a uniform distribution of fill-levels across bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 4. Compactness bias: Reward placing in bins that are already well-filled
    // Discourage creating many bins with large unused space.
    let fill_level = bin_capacity - bin_residual;
    score -= (fill_level as f64) * 0.1;

    // 5. Last chance protection: If this is the only bin that fits the current item,
    // strongly prioritize it unless the fit is catastrophic (near 0 residual).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

