    if is_new_bin {
        if fitting_bins_count == 0 {
            score = 0.0; // Must open new bin
        } else {
            // Heavily penalize opening a new bin if we have space elsewhere.
            // Scale penalty by how much space is left in current bins (mean_residual).
            score = 50.0 + (mean_residual * 2.0) + (progress * 20.0);
