                score += 25.0;
            }
        }

        // Adaptive Best Fit: If we are near the end of the stream, prioritize closing bins
        // (minimizing post_residual) more aggressively.
        if progress > 0.8 {
            score += post_residual as f64 * 0.5;
        }

        // Penalize placing items in bins that are currently "very empty" 
