    // unless the fit is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 45.0 + (progress * 20.0) } else { 0.0 };

    // Heuristic: Best-Fit Decreasing logic combined with lookahead awareness.
    // We prioritize minimizing post_residual (Best Fit), but penalize creating "dead zones"
    // (bins that are almost full but can't fit the next item).

    let mut score = post;

    // Non-linear coupling: If next_item_size is large, favor bins that leave enough space
    // to accommodate that item, effectively avoiding fragmentation.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            // Penalize bins that become "blocked" for the next item
            score += (next_item_size as f64 - post).powf(1.5);
        }
    }

    // Encourage filling bins that are already closer to the mean residual to keep
    // bin utilization uniform.
    let deviation = (post - mean_residual).abs();
