    // We add a penalty for "wasted" space in the bin.
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Lookahead: If next_item_size can fit into the current post_residual, 
    // significantly reward this placement to minimize future bin creation.
    if next_item_size > 0 && post_residual >= next_item_size {
