    }

    // 3. Pressure Management: If this is the last fitting bin, prioritize it to prevent 
    // unnecessary new bin allocation (the "new bin trap").
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 4. Harmonic Thresholding: Penalize residuals that are small but unusable 
    // (e.g., < 10) unless it's a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 20.0;
    }

    // 5. Global State Normalization: If we have many open bins, prioritize 
    // filling the most empty ones (higher residual) to converge towards fewer active bins.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 6. New Bin Penalty: If this is an empty bin (new bin candidate), apply a 
    // heavy penalty unless no other bin can fit the item.
    if bin_residual == bin_capacity {
        score += 65.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // Overrides penalty if no other options exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
