    // discouraging new bin creation as the stream progresses.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (mean_residual * 2.5) + (progress * 50.0) + 20.0
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: penalize large post_residual (wasted space)
    // but modulate based on the next item size (lookahead) to preserve space for it.
    let mut score = post;

    // If we have a lookahead item, penalize bins that cannot fit the next item
    // or bins that leave too little space for the next item.
    if next_item_size > 0 {
        let space_needed_for_next = next_item_size as f64;
        if post < space_needed_for_next {
            score += 15.0; // Penalty for stranding the next item
        } else {
