        // We scale this by the mean_residual to avoid opening new bins when
        // existing bins are already quite empty.
        score = 60.0 + (mean_residual * 0.8);
    } else {
        // 4. Density Balancing: If we are near the end of the stream, 
        // prioritize filling existing bins even if it leaves awkward gaps.
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.85 {
            score -= (bin_capacity - bin_residual) as f64 * 0.2;
        }

        // 5. Fitting Constraint: If this is the only bin that can fit the item, 
        // aggressively prioritize it to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 6. Harmonic Class Logic: Penalize "dead zones" (e.g., leaving 1-5 units)
    // which are rarely useful for future items.
    if post_residual > 0 && post_residual < 6 {
        score += 20.0;
    }

    score
