    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We define "unusable" as less than the minimum item size (assume 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that maintain a "perfect fit" potential for the next item.
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize bins that block the next item if it could have fit elsewhere.
            score += 15.0;
        }
    }

    // Harmonic/Modulo logic: prioritize filling bins to specific fractions (e.g., 1/2, 1/3, 1/4 of capacity).
    // This targets packing items into "harmonic" clusters.
    let harmonic_penalty = ((post_residual % 25) as f64) * 0.5;
    score += harmonic_penalty;

    // Strategic threshold: if only one bin can fit the item, decide whether to use it or open a new one.
    // If post_residual is very small, we might prefer a new bin to keep current bins "more empty" for larger items.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < 15 {
            score += 40.0;
        }
    }

    // Progression weight: as we reach the end of the stream, prioritize bin consolidation.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual ranges that are likely to be unusable.
    // Gaps < 10 are almost always wasted; gaps between 10-20 are difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If this is a new bin (residual == capacity), penalize it based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // If other bins can fit the item, strongly penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Global Efficiency: If the current bin's residual is significantly better than the mean, 
    // favor placing the item here to keep the mean residual high (tight packing).
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 5. Progression Weighting: As the stream nears the end, prioritize closing existing bins (lower residual)
    // rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (Minimize post_residual)
    // 2. Penalize opening new bins unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one fits
            score += 200.0 + (open_bins_count as f64 * 5.0);
        } else {
            // If it's the only option, normalize the cost
            score = 50.0;
        }
    } else {
        // 3. 2-Step Lookahead: Reward placements that fit the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Perfect fit for next item: significant reward
                score -= 45.0;
            } else {
                // If we create a gap too small for anything useful, penalize it
                if post_residual < 10 {
                    score += 30.0;
                }
            }
        }

        // 4. Mean-Residual Balancing: Avoid bins that deviate significantly from average
        // If current residual is much smaller than mean, we might be creating a "dead" bin
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // 5. Urgency factor: As we approach the end of the stream, be more conservative
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
