    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post_residual (Best Fit logic)
    let mut score = post;

    // Penalty for creating "dead zones" (small residuals that are hard to fill)
    // We penalize residuals in the range [1, 9] heavily as they are rarely useful
    if post > 0.0 && post < 10.0 {
        score += 50.0 / post;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice
    // to preserve capacity for the upcoming item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
