        }
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive 
    // about filling bins tightly to avoid opening new ones.
    // We penalize opening a new bin (where bin_residual == bin_capacity) 
    // increasingly as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    }

    // Penalize keeping too many bins open simultaneously
    score += (open_bins_count as f64) * 2.0;

    // Reward bins that align with the global mean residual to keep packing density uniform
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
