pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is small (1..9), it is likely unusable.
    // We heavily penalize creating small gaps that cannot fit the minimum expected item size.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Best-Fit/Tightness: If the item fits exactly, reward it heavily.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when existing ones are available.
    // This discourages the "new bin" candidate unless the fit is extremely poor in all current bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 5.0;
        // If we have many fitting bins, opening a new one is almost always bad.
        score += (fitting_bins_count as f64) * 20.0;
    }

    // 4. Lookahead Coupling: If the next item is large, prioritize leaving space.
    // If the next item is small, we prefer filling this bin as much as possible.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin cannot fit the next item; penalize if it's a tight fit for the current item.
            score += 5.0;
        } else {
            // This bin can fit the next item; reward slightly to keep options open.
            score -= 10.0;
        }
    }

    // 5. Global Mean Residual Alignment: Avoid bins that deviate significantly from the mean,
    // as extreme outliers in residuals often indicate poor packing efficiency.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #688: Aggressive Best-Fit Decreasing variant with lookahead-aware pressure.
    // Logic: 
    // 1. Penalize creating "dead space" (post_residual < 10, often too small to fill).
    // 2. Prioritize bins where post_residual perfectly matches the lookahead item.
    // 3. Heavily penalize opening new bins unless current bin options are severely constrained.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalty for creating fragments smaller than the smallest possible item (approx 10)
    if post_residual < 10 && post_residual > 0 {
        score += 45.0;
    }

    // Lookahead matching: reward if post_residual can accommodate the next item perfectly (or close to)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= (25.0 / (diff + 1.0));
        }
    }

    // Discourage opening new bins unless necessary
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 35.0;

        // If we have many bins, discourage opening more unless the mean residual is high
        if open_bins_count > 5 {
            score += mean_residual * 0.5;
        }
    } else {
        // Reward bins that are closer to the mean residual to keep packing density uniform
        let dev = (post_residual as f64 - mean_residual).abs();
        score -= dev * 0.1;
    }

    // If this is the only bin that fits, prioritize it over opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
