        let residual_delta = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * residual_delta;
    }

    // Dynamic constraint: As the stream progresses, prioritize closing bins 
    // by preferring smaller post_residuals (tighter packing).
    score += (progress * 10.0) * (post_residual as f64 / bin_capacity as f64);

