pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement.
    // Lower residual space is generally better (Best Fit).
    let mut score = post_res;

    // Penalty for creating 'fragmented' space (small remainders that are hard to fill).
    // We penalize residuals that are smaller than the smallest likely item (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item
        } else {
            score += 10.0; // Penalize bins that would be too small for the next item
        }
    }

    // Dynamic pressure: As the stream progresses, become more aggressive in packing
    // to avoid opening new bins late in the game.
    let exhaustion_factor = progress * 40.0;
    score += exhaustion_factor * (post_res / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily early on,
    // but reduce the penalty as we fill up or if no other bins fit.
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 50.0; // Strong disincentive to open new bins if others fit
        }
    }

    // Adjust based on the mean residual of current bins to encourage balancing
    // rather than extreme fragmentation.
    score += (post_res - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual to keep bins tight.
    // Base score is already post_residual.

    // 2. Penalty for creating "stranded" space that cannot fit common item sizes.
    // If post_residual is in the "dead zone" (less than min item size 10), it is highly inefficient.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead logic: If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that are perfectly prepped for the next item
            score -= 15.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize bins that would force a new bin for the next item
            score += 10.0;
        }
    }

    // 4. If this is the only fitting bin, heavily reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. If considering an empty bin (bin_residual == bin_capacity), apply a high baseline cost
    // to discourage opening new bins unless the fit in existing bins is truly terrible.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Adjust based on how many bins are already open to prevent fragmentation
        score += (open_bins_count as f64) * 0.5;
    }

    // 6. Harmonic-inspired adjustment: discourage residuals that are fractions of bin_capacity
    // that are unlikely to be filled by subsequent items (e.g., 50-60 range).
    if post_residual > 40 && post_residual < 60 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
