    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Harmonic penalty: If the remaining space is small but not zero, it's often 
    // "stranded" space. Penalize residues that are smaller than the next item.
    if !is_new_bin && next_item_size > 0 && post_residual < next_item_size {
