    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // New Bin Penalty: Heavily penalize opening a new bin unless the 
    // current open bins are forced into very poor fits.
    if is_new_bin {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average residual of existing bins is already very low
            // or if the current item is very large.
            score = 40.0 + (mean_residual * 0.5);
        }
    }

    // Harmonic Class logic: Prefer residues that are multiples of common item sizes (e.g., 20, 25)
    // to increase the probability that future items fit perfectly.
    let remainder_mod = post_residual % 25;
    if remainder_mod != 0 && post_residual > 0 {
        score += (25 - remainder_mod) as f64 * 0.2;
    }

    score
}

