        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bin Pressure: Discourage opening new bins (bin_residual == bin_capacity)
    // unless the fit is excellent.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5);
    }

    // 4. Fitting Scarcity: If this is the only bin that can fit the item, 
    // make it highly attractive to prevent premature new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the current bin's residual is significantly worse than the mean,
    // penalize it to encourage packing into tighter bins.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

