    // Combine factors:
    // 1. post_residual (Best Fit logic: smaller is better)
    // 2. gap_penalty (Avoid 'sliver' space)
    // 3. lookahead_reward (Lookahead optimization)
    // 4. new_bin_penalty (Control bin count growth)
    // 5. deviation_penalty (Uniformity)
    let score = post + gap_penalty + lookahead_reward + new_bin_penalty + deviation_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest residual.
    // Penalty for large post_residual to avoid fragmentation.
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class Logic: Penalize residuals that cannot fit common item sizes.
    // Small residuals (1-9) are often "dead space" because min item size is 1.
    if post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Synergy: If next_item_size fits in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. New Bin Thresholding: If we are forced to open a new bin, assess if the current 
    // open bins are "too full" to accept upcoming items (based on mean_residual).
    if bin_residual == bin_capacity {
        // Only open new if open bins are unlikely to accommodate the current item efficiently
        if (mean_residual > item_size as f64) && (fitting_bins_count > 0) {
            score += 100.0;
        } else {
            score += 20.0;
        }
    }

    // 5. Progression scaling: As we reach the end of the stream, prioritize packing 
    // tightly to reduce the number of bins opened in the final phase.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    // 6. Penalty for creating isolated bins: If we have many open bins, 
    // penalize creating a new one unless it's a perfect fit.
    if bin_residual == bin_capacity && open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
