        } else if post_residual > next_item_size {
            // Reward bins that are "promising" for the next item
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize bins that cannot fit the next item if they could have otherwise
            score += 10.0;
        }
    }

    // 3. Global state awareness:
    // If the item fits into only one bin, we are forced to take it unless we open a new one.
    // If fitting_bins_count is low, we prioritize closing off bins.
    if fitting_bins_count == 1 && bin_residual > item_size {
        score -= 5.0;
    }

    // 4. Distributional balance:
    // If the current bin's residual is significantly lower than the mean_residual, 
    // it is a "tight" bin; prioritize filling it to keep the average high.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. New bin penalty:
    // If this is a new bin (residual == capacity), add a significant penalty
    // unless all other options are objectively worse (which the score logic handles).
    if bin_residual == bin_capacity {
        score += 35.0;
        // Dynamically adjust new bin cost based on progression
        let progress = step_index as f64 / total_items as f64;
        score += (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
