    // If post_residual is small but not zero, it's likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, 
    // significantly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global State: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0);
        // If there are bins that can fit the item, strongly penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Dynamic Time Horizon: As we reach the end of the stream, 
    // prioritize packing tightness over bin count conservation.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64 * 0.5);
    }

    // 5. Balance the bin residuals: Penalize bins that deviate from the mean residual.
    // This encourages keeping bins at similar fullness levels (Best Fit variant).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
