    // to keep the fill-levels consistent across the set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Progression Scaling: As the stream nears the end, prioritize closing bins
    // by being more aggressive with fitting items into existing gaps.
    let progress = step_index as f64 / total_items as f64;
    score -= (progress * 15.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin (if fitting_bins_count > 0, penalize new bin creation)
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 2. Lookahead: prioritize bins that can perfectly or optimally contain the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // Strong reward for perfect 2-step fit
        } else if post_residual > next_item_size {
