            score += 10.0;
        }
    }

    // 3. Efficiency heuristic: avoid creating "slivers" (very small residuals)
    // If post_residual is < 10, it is likely to remain empty waste for the rest of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Global balance: prefer bins that align with the current mean_residual
    // This helps keep bins packed at similar levels to reduce variance
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. Progression awareness: tighten constraints as the stream nears completion
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late stage: strongly punish any waste
        score += post_residual as f64 * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
