    // However, avoid creating "slivers" (very small residuals < 10) which are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Coupling: If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        let potential_after_next = post_residual as i32 - next_item_size as i32;
        if potential_after_next >= 0 {
