pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post-residuals that are too small to be useful for future items (1..9).
    // If post_residual is in [1, 9], it's highly likely to remain dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly or near-perfectly into the post_residual,
    // lower the score to encourage this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = (post_residual - next_item_size) as f64;
        if gap_after_next < 5.0 {
