    // This forces the algorithm to fill existing bins rather than opening new ones unless the fit is excellent.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // If this is the only bin that fits the item, don't penalize too heavily.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // 4. Mean Residual Balancing: Favor bins that keep the overall mean residual consistent.
    // If this bin's post_residual is significantly lower than the current mean, it's a good candidate.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Progression Weighting: As we approach the end of the stream, prioritize closing bins
    // by aggressively filling them (reducing post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
