    // to force packing into existing bins later in the sequence.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 25.0 + (progress * 50.0) } else { 0.0 };

    // Primary objective: Minimize post_residual (Best Fit).
    // Coupling: If post_residual is too small (e.g., < 10), it creates "dead space" that
    // is unlikely to fit future items. We apply a non-linear penalty to very small residuals.
    let dead_space_penalty = if post < 10.0 && post > 0.0 {
