    // to keep bin utilization uniform across the open set.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily unless fitting_bins_count is 0.
    // This forces the algorithm to use existing bins unless they are all poor fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 10.0; // Prefer new bin over overflowing/impossible states
        }
    }

    // Progression scaling: As we approach the end of the stream, prioritize packing tightly (lower residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // Harmonic modulo penalty: Penalize residuals that are not multiples of common item sizes (e.g., 20, 25).
    // This helps align bin space for future items in a repeating distribution.
    if post_residual % 20 != 0 && post_residual % 25 != 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

