        score -= 20.0 * (1.0 - progress);
    }

    // Encourage balancing residuals across open bins to maintain flexibility.
    // If this bin's post-residual deviates significantly from the mean, add a cost.
    let dev = (post - mean_residual).abs();
    score += dev * 0.1;

    // Discourage opening new bins too early by penalizing the "Empty Bin" case
    // unless the fit in existing bins is exceptionally poor.
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize leaving small, unusable gaps (1-9)
    if post_residual > 0 && post_residual < 10 {
