    }

    // 2. Harmonic Class Alignment: Favor residuals that are multiples of common item sizes (e.g., 20, 25)
    // This encourages "clean" space for future items.
    if post_residual % 20 == 0 {
        score -= 15.0;
    } else if post_residual % 25 == 0 {
