        }
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless the current residual is very poor
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 35.0;

        // If many bins are open, discourage opening another unless essential
        score += (open_bins_count as f64) * 2.0;

        // If we are near the end of the stream, be more conservative
        let progress = step_index as f64 / total_items as f64;
