    // 5. Fitting Constraint: If this is the only bin that fits the item, make it highly attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Mean Residual Balancing: Avoid bins that deviate significantly from the mean
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

