    // We already have post_residual in score, but we penalize very small, unusable gaps (1-5)
    if post_residual > 0 && post_residual < 6 {
        score += 15.0;
    }

    // 3. Lookahead Logic: If the next item can fit in this bin, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Global State: If we have many open bins, penalize opening another one
    if is_new_bin {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Fitting Constraint: If this is the only bin that can fit the item, prioritize it strongly
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 6. Mean Residual Balancing: If the bin's residual is significantly better than the mean, prefer it
    if !is_new_bin && (post_residual as f64) < mean_residual {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9) as the stream progresses, 
    // but allow them early on to keep bins open.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_res) * (1.0 + progress * 5.0)
    } else {
        0.0
    };

    // Factor in the next item: if the current bin can fit the next item, reward it.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -20.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Prefer bins that are closer to the mean residual to maintain packing density balance.
    let stability_weight = (post_res - mean_residual).abs() * 0.5;

    // Discourage opening new bins (bin_residual == bin_capacity) unless they are highly efficient.
    // As the stream progresses, the penalty for opening a new bin increases.
    let open_new_bin_penalty = if bin_residual == bin_capacity {
        40.0 + (progress * 60.0)
    } else {
        0.0
    };

    // Final score: Lower is better.
    // We prioritize Best-Fit (minimizing post_residual) but modulate with lookahead and progression.
    post_res + dead_space_penalty + lookahead_bonus + stability_weight + open_new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // We favor bins that become very tight (Best-Fit principle).
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic:
    // If post_residual is small but not zero, it creates "unusable" gaps.
    // We reward bins that leave a post_residual that is a multiple of common item sizes (e.g., 20, 25).
    if post_residual > 0 && post_residual < 20 {
        score += 15.0; // Penalty for creating "sliver" gaps that are hard to fill
    }
    if post_residual % 25 == 0 {
        score -= 10.0; // Reward creating "clean" multiples of 25
    }

    // 3. Lookahead Integration:
    // If next_item_size can fit into the new post_residual, drastically reduce score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Scarcity/Open Bin Management:
    // If this is the last fitting bin, we are forced to use it unless the new bin is better.
    // We penalize opening a new bin (bin_residual == bin_capacity) unless the mean_residual is very low.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 50.0; // Heavy penalty for opening new bins if existing ones have space
        } else {
            score += 5.0; // Neutral baseline for opening new bins
        }
    }

    // 5. Progression weighting:
    // As we approach the end of the stream, prioritize packing tighter (Best-Fit focus).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
