    // opening new bins unless the fit in existing bins is statistically poor.
    if bin_residual == bin_capacity {
        score += 65.0;
    }

    // 4. Mean Residual Balancing: If the post_residual is significantly worse than the current
    // average, penalize it to maintain uniform bin utilization across the set.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

