        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. New Bin Thresholding: If this is an empty bin, add a dynamic threshold cost.
    // We only open a new bin if the best existing fit is significantly worse than perfect.
    if bin_residual == bin_capacity {
