    // 4. Fitting Pressure: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 5. Mean residual alignment: Avoid bins that deviate significantly from the global average.
    // This helps keep bins packed at similar levels.
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    // 6. Progressive packing: As we near the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
