pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a new bin: proportional to progress to encourage consolidation early
    // and discourage opening new bins as the stream nears completion.
    if is_new_bin {
        score += 25.0 + (progress * 50.0);
    }

    // Non-linear coupling: penalize small, unusable post-residuals (the "fragmentation" trap).
    // If post_residual is small (e.g., 1-9), it's likely dead space.
    if !is_new_bin && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we effectively "waste" the capacity for the next step.
    if next_item_size > 0 && !is_new_bin {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Global state awareness: encourage using bins that align with the mean_residual
    // to keep the bin distribution uniform.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // Final scaling: favor bins that are harder to fill (fewer fitting bins) 
    // to preserve capacity in "flexible" bins.
    if fitting_bins_count > 0 {
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily favor bins where post_residual is small.
    // Penalty for leaving large gaps: exponential growth on post_residual.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward placements that leave a residual which is a multiple 
    // of common item sizes (e.g., 20, 25, 33) to allow future packing.
    let harmonic_penalty = ((post_residual % 20) as f64) * 0.5;
    score += harmonic_penalty;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, 
    // we reward this bin significantly to encourage tight pairing.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 4. Scarcity/Efficiency weighting:
    // If this is the last chance for the current item (fitting_bins_count == 1),
    // we make it very attractive to prevent opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Empty Bin Threshold:
    // Only choose a new bin if the current post_residual is particularly bad (e.g., < 10)
    // or if we have many bins open and should consolidate.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, adjusted by progress and open bin count.
        score = 65.0 + (open_bins_count as f64 * 0.5) - ((step_index as f64 / total_items as f64) * 10.0);
    }

    // 6. Penalty for creating "dead zones" (residuals too small to fit any item, e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residual values that fall into "unusable" ranges (1..9).
    // An item size is at least 10, so a residual < 10 is effectively a "dead" gap.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open bin pressure: Penalize opening new bins when existing ones could fit the item.
    // If this is a new bin (bin_residual == bin_capacity) and fitting_bins_count > 0, penalize heavily.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
