        if post_residual < 10 {
            score += 20.0;
        }

        // 5. Mean Deviation:
        // Favor bins that align with the current average density of the packing state.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 6. Final Opportunity Adjustment:
    // If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
