    }

    // Discourage opening new bins early in the stream, but allow it if the 
    // fit is exceptionally good (post_residual near 0).
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress);
        if post == 0.0 {
            score -= 10.0;
        }
    }

    // Couple with mean_residual to balance the load across open bins.
    // Penalize bins that are significantly emptier than the average.
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.5 * residual_diff.powi(2) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
