    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // Penalty for creating "sliver" waste.
    }

    // 2. 2-Step Lookahead: Reward bins that perfectly accommodate the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // Strong reward for perfect match potential.
        } else if post_residual > next_item_size {
            score -= 10.0; // Moderate reward for keeping room for next item.
        } else {
            score += 20.0; // Penalty if current placement blocks the next item from fitting here.
        }
    }

    // 3. Global Bin Density Management: 
    // If the bin is new (bin_residual == bin_capacity), penalize opening it unless necessary.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0; // Strong disincentive to open new bins if existing ones fit.
        } else {
            score -= 20.0; // Prefer opening new bin if no existing bin is viable.
        }
    }

    // 4. Mean Residual Coupling: 
    // Penalize bins that deviate significantly from the average residual of open bins 
    // to encourage uniform packing density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Progression Weighting:
    // As we approach the end of the stream, prioritize closing bins (tight fits) over balancing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 15 {
        score -= 30.0; // End-game: aggressive compaction.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
