    // We penalize larger post_residuals heavily to keep bins tight.
    let mut score = post * post;

    // Penalty for leaving a 'dead zone' that is too small for most expected future items.
    // If post_residual is < 10, it's likely wasted space.
    if post > 0.0 && post < 10.0 {
        score += 500.0 / (post + 1.0);
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin to prepare for a "perfect" packing sequence.
    if next_item_size > 0 && post >= next_item_size as f64 {
