    // Dynamic pressure: As the stream progresses, become more aggressive about filling
    // existing bins rather than opening new ones.
    // fitting_bins_count acts as a critical signal; if only one bin fits, 
    // we should prioritize it unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0 * (1.0 - progress);
    }

    // New bin handling: If bin_residual == bin_capacity, this call represents opening a new bin.
    // We penalize this heavily early on, but allow it if the current open bins are 
    // "cluttered" (mean_residual is low).
    if bin_residual == bin_capacity {
