    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 50.0;
    }

    // 3. Penalty for fragmentation: If the post_residual is small but unusable
    // (e.g., < 10, since items are >= 10), it's dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Global state adjustment: Encourage using bins that are already open
    // rather than opening new ones, unless the new bin is objectively better.
    if bin_residual == bin_capacity {
        // This is a new bin. Penalize it unless the current average residual is very high.
        // We want to force usage of existing bins if they have enough room.
        score += 30.0 + (mean_residual * 0.5);
    }

    // 5. Urgency factor: As we near the end of the stream, prioritize space consolidation.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual > 20 {
        score += 15.0 * progress;
    }

    // 6. Scarcity factor: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

