        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Non-linear coupling: Modulo-based preference for "clean" residual remainders
    // This helps group similar sizes together implicitly.
    let remainder_mod = (post_residual % 20) as f64;
    score += remainder_mod * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
