    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 25.0; // Penalty for making a bin unable to fit the next item
        }
    }

    // 5. Progression Scaling: As the stream nears the end, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score (Best Fit Decreasing variant with lookahead)
    // post_residual: 0 is perfect, higher is worse (more wasted space)
    let mut score = post_residual as f64;

    // 1. Penalty for creating "stranded" space that is too small for any future item
    // If post_residual is small (e.g., < 10), it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead: Reward bins that fit the next item perfectly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward if the current placement leaves space for the next item
            let slack = post_residual - next_item_size;
            score -= (100.0 - slack as f64) * 0.5;
        } else {
            // Penalize if current placement forces a new bin for the next item
            score += 15.0;
        }
    }

    // 3. Heuristic: Balance the load across bins
    // If the bin is emptier than the mean, prefer filling it to keep residuals uniform
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 4. Force selection of new bins only when necessary
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no good fits (fitting_bins_count == 0)
        // or if our current bins are already too fragmented.
        if fitting_bins_count > 0 {
            score += 40.0;
        } else {
            score -= 10.0;
        }
    }

    // 5. Progression scaling: Be more aggressive as we reach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) logic: prioritize bins that leave the least space.
    // We favor post_residual being small (tighter packing).

    // 2. Penalty for creating "dead zones": If post_residual is small but > 0, 
    // it's hard to fill. If it's 0, it's perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 3. Lookahead integration: If next_item_size is large, avoid bins that leave 
    // a tiny sliver of space that can't fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 40.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // 4. Global state awareness: If we are near the end of the stream, 
    // be more aggressive in filling existing bins to minimize total bins opened.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // 5. New Bin Logic: Only open a new bin if the current fit is terrible.
    // If bin_residual == bin_capacity (New Bin Case):
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Must open a new bin.
            score = 0.0;
        } else {
            // Penalize opening a new bin if we have fitting candidates.
            score += 60.0 + (open_bins_count as f64 * 5.0);
        }
    }

    // 6. Mean residual balancing: Penalize deviation from mean to keep bins uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // We add a penalty for larger post_residuals to prefer tighter fits.
    let mut score = post * 1.5;

    // Penalty for creating a bin that is too empty early in the stream, 
    // but allow flexibility as we approach the end of the stream.
    // If we have a very small residual, we reward it to keep the bin tight.
    if post < 10.0 {
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // strongly reward this bin to achieve Best Fit + One-Step Lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // If this is the last chance for the current item (fitting_bins_count == 1),
    // and the post_residual is very small (e.g., < 5), we heavily prioritize this bin.
    if fitting_bins_count == 1 && post < 5.0 {
        score -= 50.0;
    }

    // Penalty for opening a new bin:
    // Only open a new bin if the current fit is extremely poor (post_residual is large)
    // or if we are at the very beginning of the stream where bin count matters less.
    if bin_residual == bin_capacity {
        score += 35.0 + (20.0 * progress);

        // If we have many open bins, penalize opening a new one further.
        score += open_bins_count as f64 * 2.0;
    }

    // Coupling with mean_residual: If this bin's post_residual is significantly 
    // worse than the average, penalize it to maintain uniform bin filling.
    if post > mean_residual {
        score += (post - mean_residual) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
