        } else if post_residual >= next_item_size {
            // If it fits with room to spare, subtract based on how tight the fit is.
            score -= (next_item_size as f64) * 0.5;
        } else {
            // Penalize leaving a gap that is too small for the next item.
            score += 20.0;
        }
    }

    // 4. Global State Optimization:
    // Avoid opening a new bin if we have plenty of open bins.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty relative to open_bins_count.
    if bin_residual == bin_capacity {
