    score += (post_residual as f64) * 0.5;

    // 2. Lookahead Synergy: If the post_residual can perfectly or nearly perfectly accommodate the next item,
    // we drastically lower the score to prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
