    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already very low,
        // suggesting they are too crowded to be useful for future large items.
        if mean_residual > 20.0 {
            score += 10.0;
        } else {
            score += 80.0; // Strong penalty for opening new bins prematurely
        }
    }

    // 5. Fragmentation Avoidance: Penalize leaving small, unusable gaps (1-9 range)
    // which are statistically likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
