    // that are too small to fit common items (e.g., < 20).
    if post_res > 0.0 && post_res < 20.0 {
        score += (20.0 - post_res).powf(1.5);
    }

    // Lookahead logic: if we have a next item, we want to ensure the current bin 
    // can accommodate the future item if possible, or save that space.
    if next_item_size > 0 {
        if post_res >= next_item_size as f64 {
            // Reward bins that can fit the next item (synergy)
            score -= (next_item_size as f64) * 0.5;
        } else {
            // Penalize bins that render themselves unable to fit the next item 
            // if they were close to doing so.
            score += (next_item_size as f64 - post_res) * 0.3;
        }
    }

    // Dynamic adaptation: as the stream progresses, prioritize closing bins 
    // over opening new ones. If fitting_bins_count is 1, we are at a critical 
    // juncture to pack the current bin instead of starting a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Global bin count management: slightly penalize opening new bins 
    // as we get closer to the end of the stream to force consolidation.
    if bin_residual == bin_capacity {
        score += 15.0 + (progress * 20.0);
    }

    // Coupling with mean_residual: penalize deviations from the mean to keep
    // bin usage uniform across the set.
    score += (post_res - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that cannot fit common item sizes (10-80).
    // If post_residual is small but > 0, it's often better to fill it perfectly.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the immediate next item
            score -= 25.0;
        } else if post_residual > 0 {
            // Penalize bins that 'waste' space that could have been used for next_item_size
            score += 15.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        }
    }

    // Harmonic class logic: prioritize bins that align with divisors of bin_capacity (e.g., 20, 25, 50).
    // This helps keep bins in "compatible" states.
    let remainder = post_residual % 20;
    if remainder == 0 {
        score -= 10.0;
    }

    // If this is the only fitting bin, reduce penalty for poor fit to avoid opening new bins prematurely.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Dynamic thresholding: as we progress through the stream, become more conservative about opening new bins.
    if is_new_bin {
        // Higher penalty for new bins as the stream progresses
        score += (open_bins_count as f64 * 2.0) + (progress * 40.0);
    } else {
        // Reward bins that are closer to the mean residual to keep distribution uniform
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

