    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item is large and won't fit the current post_residual, 
    // penalize the current choice to preserve space for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bins pressure: If we have many bins open, favor filling existing bins aggressively.
    // If we have very few, be more conservative about packing to keep capacity for future items.
    score += (open_bins_count as f64) * 2.5;

    // 4. Fitting constraints: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 {
