    }

    // 5. New Bin logic: If bin_residual == bin_capacity, we are evaluating a "New Bin".
    // Heavily penalize opening a new bin unless the current mean_residual is very low (bins are full).
    if bin_residual == bin_capacity {
        score += 15.0 + (100.0 - mean_residual);
    }

    // 6. Progress factor: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

