    }

    // 4. Critical threshold: If this is the last chance to fit an item in an existing bin,
    // lower the score to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize 
