        score = 25.0 + (open_bins_count as f64 * 0.5) + (progress * 15.0);
    } else {
        // Best Fit Decreasing logic: prioritize smaller post_residuals (tighter fits).
        // Penalty for leaving space that is too small for any likely future item.
        if post_residual < 10 {
            // "Perfect" or "Near-Perfect" fit: reward it.
            score -= 15.0;
        }

        // Lookahead adjustment: If the next item fits into the current post_residual,
        // we reward keeping this bin as a target for that future item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }

        // Global state awareness: If we have many bins open, try to consolidate by 
