        if (bin_residual as f64) > mean_residual {
            score += 5.0;
        }

        // Urgency: If this is the only bin that fits the item, make it very attractive.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Final constraint: Ensure we don't return negative scores that might confuse 
        // the logic against the new-bin base score.
        if score < 0.0 {
            score = 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bins heavily early on, but allow flexibility as the stream ends.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (50.0 * (1.0 - progress)) + (20.0 * open_bins_count as f64 / (open_bins_count + 1) as f64)
    } else {
        0.0
    };

    // Reward tighter fits (lower post_residual) but penalize "near-empty" 
    // slivers that are impossible to fill later (e.g., post_residual < 10).
    let sliver_penalty = if post < 10.0 && post > 0.0 {
        15.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead logic: if the next item is large, prefer bins that can accommodate it.
    let lookahead_alignment = if next_item_size > 0 {
        let fits_next = if post >= next_item_size as f64 { -10.0 } else { 5.0 };
        fits_next * (1.0 - progress)
    } else {
        0.0
    };

    // Heuristic: Minimize post_residual (Best Fit) with non-linear penalties for fragmenting space.
    let mut score = post + new_bin_penalty + sliver_penalty + lookahead_alignment;

    // Favor bins that keep the mean residual balanced to prevent "bin starvation".
    score += (post - mean_residual).abs() * 0.2;

    // If this is the last chance for the current item, reduce penalty to avoid unnecessary new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
