}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins where post_residual is minimized.
    // We treat the NEW-BIN candidate (bin_residual == bin_capacity) as a last resort.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base it on the average density we expect.
        // If we have many open bins, opening a new one is discouraged.
        score = 85.0 + (open_bins_count as f64 * 2.5);
    } else {
