                score += 15.0;
            }
        }

        // 3. Balance against mean_residual: avoid creating bins that are significantly 
        // more empty than the current average.
        if (post_residual as f64) > mean_residual {
            score += (post_residual as f64 - mean_residual) * 0.5;
        }

        // 4. Scarcity penalty: if this is the only bin that can fit the item, 
        // we might want to save it if the item size is very large.
