    };

    // Dynamically adjust strategy based on stream progress.
    // Early in the stream, favor tight packing. Late in the stream, be more aggressive
    // to consolidate remaining items into fewer bins.
    let progress_modifier = (1.0 - progress) * (mean_residual / 10.0);

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // fitting bins currently exist. Opening a new bin is only desirable if fitting_bins_count is low.
    let new_bin_penalty = if bin_residual == bin_capacity {
