    // 3. Global State Balancing: Use mean_residual to prevent fragmentation.
    // If this bin's residual is significantly tighter than the mean, prioritize it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0 * (1.0 - progress);
    }

    // 4. New Bin Thresholding: Dynamic bias against opening new bins.
    // As we approach the end of the stream, be more conservative with opening new bins.
    if bin_residual == bin_capacity {
