    }

    // 5. Fitting Constraint: If this is the last bin that can fit the item, 
    // apply a strong discount to ensure we don't unnecessarily open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Density Reward: Favor bins that are getting fuller as the stream progresses.
    if progress > 0.5 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
