pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits (Best Fit Decreasing logic)
    // We penalize larger post_residuals to force tight packing.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, heavily reward it.
    // This reduces fragmentation by creating "perfect" pairings.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 5.0;
        // Further refine: reward if the resulting secondary residual is very small (near-empty bin)
        let secondary_residual = post_residual - next_item_size;
        if secondary_residual < 10 {
            score -= 20.0;
        }
    }

    // 3. Mean Residual Balancing: Avoid creating bins that are significantly worse than the current average.
    // If post_residual is much larger than the mean_residual, penalize to keep bin usage dense.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 2.0;
    }

    // 4. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless necessary.
    // We only open a new bin if the best existing fit is extremely poor (post_residual > 30).
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 5. Criticality: If this is the only fitting bin, lower the penalty to prevent overflow.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Progression scaling: As we reach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best-Fit principle: minimize wasted space)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if is_new_bin {
        // Only consider new bin if we are forced or if the average residual is very high
        // If fitting_bins_count > 0, we penalize new bin heavily to force Best-Fit
        score += (fitting_bins_count as f64) * 50.0;

        // Dynamic thresholding: as we near the end of the stream, be more conservative with new bins
        score += (1.0 - progress) * 20.0;
    } else {
        // Reward bins that are becoming "tight" (Best-Fit variant)
        // We want to reduce the residual to near zero
        score -= (bin_capacity - bin_residual) as f64 * 0.1;

        // Lookahead heuristic: If the next item fits into the current post_residual, 
        // prioritize this bin to prevent fragmentation.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // If this is the last chance to fit the item in an open bin, reward it
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Global state adjustment: If mean_residual is high, we are being inefficient.
    // Tighten the requirements for existing bins to consolidate space.
    if mean_residual > 30.0 {
        score += (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best-Fit principle).
    let mut score = post_res;

    // Penalty for creating "dead space": residues that are too small to fit typical future items.
    // We dampen this penalty as we approach the end of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0 * (1.0 - progress);
    }

    // Lookahead interaction: if next_item_size is large, favor bins that preserve space
    // or bins that are already "near-full" to avoid stranding the large item.
    if next_item_size > 60 {
        score += (100.0 - post_res) * 0.5;
    }

    // Dynamic thresholding: if this is the only bin that can fit the item, 
    // we heavily discount the score to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Global load balancing: penalize opening new bins if the current bins have plenty of space.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += mean_residual * 0.8;
    }

    // Non-linear coupling: slightly penalize leaving large residuals in early stages 
    // to keep the number of active bins manageable as the stream progresses.
    score += (post_res / 100.0) * (progress * 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'fragmentation' zones (small remainders that are hard to fill)
    // We prioritize keeping residuals in ranges that can accommodate common item sizes (e.g., 20-30)
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // Lookahead logic: if the next item is large, prefer bins that leave enough room
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for blocking the next item from this bin
            score += 25.0;
        } else {
            // Reward for keeping the next item in mind
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // New bin avoidance: If we have fitting bins, heavily penalize opening a new one
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0 + (open_bins_count as f64 * 2.0);
    }

    // Harmonic preference: Favor bins that reach specific capacity thresholds
    // Residuals near 0 (perfect fit) are always ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Balance across bins: Penalize bins that deviate significantly from the mean residual
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Progression scaling: As we approach the end of the stream, prioritize packing density over flexibility
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that are too small to be useful
    // (e.g., < 10) as they create "unusable" gaps, unless they are exactly 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bins Pressure: Discourage opening new bins if we have many already,
    // unless the fit is exceptionally good.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 3. Lookahead Sensitivity: If the next item is large, prioritize keeping 
    // larger residuals available in existing bins.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item,
    // reward it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the current residual is already low (below mean),
    // prioritize completing the bin to minimize total active bin count.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (Best Fit).
    // The base score (post_residual) already favors filling bins tightly.

    // 2. Penalty for opening new bins:
    // If the bin is brand new, add a significant penalty to force using existing bins.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 3. Lookahead Matching (The "Aggressive Match"):
    // If the next item fits perfectly into the remaining space, reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward configurations where the gap after the next item is minimized (near 0)
        score -= (25.0 - diff * 0.5);
    }

    // 4. Mean Residual Balancing:
    // If the current post_residual is much larger than the global mean, we penalize it 
    // to encourage keeping the bin density high across the board.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Urgency factor:
    // If this is the only bin that can fit the item, we are forced to use it. 
    // If we have many options, we can be more selective.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 6. Progression scaling:
    // As we approach the end of the stream, prioritize clearing existing bins 
    // (lower penalty for new bins to allow cleanup).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if is_new_bin {
        // Only consider a new bin if we have many open bins or it's very late in the stream
        // Otherwise, heavily penalize creating a new bin
        score += 45.0 + (progress * 20.0);

        // If other bins can fit the item, discourage opening a new one
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    } else {
        // Lookahead heuristic: penalize placements that leave a residual 
        // that cannot accommodate the next item (if next_item_size is known)
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
        }

        // Penalize creating "dead space" that is likely to remain unused
        // (Residuals < 10 are often hard to fill)
        if post_residual < 10 && post_residual > 0 {
            score += 25.0;
        }

        // Favor bins that stay close to the global mean residual to keep bins uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Dynamic pressure: as the stream nears the end, prioritize closing bins
    // by preferring to fill existing bins over starting new ones
    if progress > 0.8 && !is_new_bin {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: higher at the start, lower towards the end
    // to allow consolidation as the stream finishes.
    if is_new_bin {
        score += 15.0 + (35.0 * (1.0 - progress).powf(1.5));
    }

    // Lookahead interaction: 
    // If we have a next item, penalize bins that leave a 'dead zone' (e.g., 1-9 residual)
    // which is unlikely to fit most future items.
    if next_item_size > 0 {
        let dead_zone_penalty = if post_residual > 0 && post_residual < 10 {
            15.0 * (1.0 - (post_residual as f64 / 10.0))
        } else {
            0.0
        };
        score += dead_zone_penalty;
    }

    // Density optimization: 
    // If the bin is the last one that can fit the item, we are forced to take it.
    // However, if we aren't forced, we penalize bins that deviate significantly 
    // from the current mean residual to keep bin fill levels balanced.
    if !is_new_bin && fitting_bins_count > 1 {
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * residual_diff;
    }

    // Adaptive pressure: If open_bins_count is high relative to progress, 
    // aggressively force tighter packing.
    let density_pressure = (open_bins_count as f64 * (1.0 - progress)) * 2.0;
    score += density_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We favor bins where post_residual is small (tight fit)

    // 2. Harmonic Class logic:
    // If post_residual is small enough to potentially fit the next item, reward it.
    // We identify "harmonic buckets" where the post_residual is a multiple of next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that leave exactly enough space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;

            // Penalty for stranding an item: if post_residual < next_item_size,
            // we create "dead space" that is too small for the predicted next item.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless the open bins are already very full (mean_residual is low).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is proportional to how much room is left in existing bins
        score += mean_residual * 2.0;

        // If we have many fitting bins, opening a new one is almost always suboptimal
        score += (fitting_bins_count as f64) * 50.0;
    }

    // 4. Progression weighting:
    // Toward the end of the stream, prioritize closing bins to reduce total count
    let progress = step_index as f64 / total_items as f64;
    if post_residual == 0 {
        score -= 20.0 * progress;
    }

    // 5. Modulo-based penalty:
    // Avoid leaving "odd" remainders that are unlikely to match future items
    // (Sizes are often clustered, favoring multiples of 10 or 25)
    let remainder_mod = (post_residual % 10) as f64;
    score += remainder_mod * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
