    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // 2. Lookahead Integration: If the next item cannot fit in the post_residual,
    // we penalize that bin to encourage saving it for the next item.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (residual == capacity), penalize it based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If there are other bins that could fit this item, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tightness Reward: Favor bins where the post_residual is very close to 0 (perfect fit).
    if post_residual == 0 {
        score -= 20.0;
    }

    // 5. Global Efficiency: As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
