            score -= (bin_capacity - post_residual) as f64 * 0.5;
        } else {
            // Penalize bins that leave "dead space" smaller than the next item
            score += next_item_size as f64 * 0.8;
        }
    }

    // 2. Harmonic Class Logic: Prefer filling bins to specific thresholds 
    // to keep residuals aligned with common item sizes (e.g., 20, 25, 33, 50).
    let harmonic_penalty = (post_residual % 20) as f64 * 1.5;
    score += harmonic_penalty;

    // 3. New Bin Threshold: Discourage opening new bins unless the fit is truly poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if we have many open bins already or if the average 
        // residual is high (i.e., we are already failing to pack efficiently).
        if open_bins_count > 0 && mean_residual < 25.0 {
            score += 45.0; 
        } else {
            score += 15.0;
        }
    }

    // 4. Scarcity Factor: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 5. Progression Scaling: As the stream nears the end, prioritize tight packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
