            score -= 10.0;
        }
    } else {
        // Bias towards bins that are already "half-full" to consolidate space.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;

        // Penalize bins that deviate significantly from the mean residual of all open bins (load balancing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
