    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead space" that is too small for any likely future item.
    // If post_residual is small but not zero, it's often a waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead integration: If next_item_size is large, favor keeping larger residuals.
    // If next_item_size > post_residual, we penalize this bin because it can't fit the next item.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0;
    }

    // 4. If this is the only bin that fits, we are forced to take it. 
    // Reward this to prevent opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global state management: Balance the usage of open bins.
    // If we have many open bins, penalize opening a new one.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Penalty for opening a new bin is proportional to the mean residual of existing bins.
            // If mean_residual is high, we have space elsewhere; don't open a new bin.
            score += 40.0 + (mean_residual * 0.5);
        }
    }

    // 6. Dynamic time horizon: As we approach the end of the stream, prioritize tight packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late stage: penalize any residual space significantly.
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
