    // to avoid creating clusters of very full or very empty bins.
    let balance_factor = (post - mean_residual).abs() * 0.5;

    // Final score: prioritize lower values.
    // We combine the base post_residual with non-linear penalties.
    post + sliver_penalty + new_bin_penalty + lookahead_penalty + balance_factor
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

