    // Minimizing post_residual is the baseline.

    // 2. Penalty for creating "dead zones" (unusable space < 10)
    // If the post_residual is small but > 0, it's often wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - (post_residual as f64 * 2.5);
