    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless the mean_residual of existing bins is already very low (high fragmentation).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many fitting options.
        score += 30.0 + (fitting_bins_count as f64 * 15.0);

        // If current bins are mostly full (mean_residual < 20), opening a new bin is slightly more acceptable.
        if mean_residual < 20.0 {
