    // 5. Progress-dependent scaling:
    // As we approach the end of the stream, prioritize clearing remaining items into existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
