    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize leaving small, unusable gaps.
    // Gaps < 10 are almost impossible to fill given the input distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Best-Fit Bias: Prefer bins that leave the least space (standard Best-Fit behavior).
    // We reinforce this by keeping the base score as post_residual.

    // 3. Lookahead Synergy: If the next item can fit in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Bin Pressure: If this is the only bin that fits the item, make it very attractive
    // to avoid the overhead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: Penalize opening new bins if the mean residual is high.
    // If we have many open bins with large residuals, try to consolidate.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 0.5);
        if mean_residual > 30.0 {
            score += 20.0;
        }
    }

    // 6. Progress Scaling: As the stream nears the end, prioritize closing bins
    // by being more aggressive about filling existing ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize empty bin creation unless absolutely necessary.
    // If we have other options, make the empty bin score high.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0;
    }

    // 2. Best-Fit logic: prefer smaller post_residual (already in base score).
    // Heavily penalize large gaps that are too small to fit common items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead matching: If post_residual is close to next_item_size, reward it.
    // This creates "perfect fits" for the next step.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 4. Mean residual balancing: Penalize bins that deviate significantly from the mean.
    // Keeping residuals uniform helps ensure future items have a consistent target.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Urgency: If only one bin fits, prioritize it to avoid creating new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 6. Progressive packing: As the stream nears completion, favor tighter packing 
    // to close out bins and reduce count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}
